            // ---- the funding screen and the five facilities ------------------------------------------
            ["funding.title"] = "BANK & DONATIONS",
            ["funding.borrowing"] = "BORROWING",
            ["funding.strap"] = "Founders hold {0} after {1} round(s). Raised {2} in total. Investor mood is {3}.",
            ["loan.commercial"] = "COMMERCIAL",
            ["loan.state"] = "STATE PROGRAMME",
            ["loan.monthly_instalment"] = "MONTHLY INSTALMENT",
            ["loan.monthly_commission"] = "MONTHLY COMMISSION",
            ["loan.back_in_total"] = "BACK IN TOTAL",
            ["loan.open_facilities"] = "OPEN FACILITIES",
            ["loan.terms"] = "{0} term, {1} before the first instalment",
            ["loan.left_of"] = "{0} left of {1}",
            ["loan.nothing_drawn"] = "Nothing drawn. A facility is cash now against a fixed sum on a fixed date, whether or not the quarter went well.",
            ["loan.bridge.name"] = "Bridge facility",
            ["loan.bridge.desc"] = "Six months of runway from a lender who expects a round to close behind it. Small, fast, and priced as if the round might not.",
            ["loan.equipment.name"] = "Equipment finance",
            ["loan.equipment.desc"] = "Borrowed against the accelerators rather than against the company. The lender does not care what the models do, only what the hardware would fetch, so it is cheap and it is small. Miss the schedule and the fleet is what they take.",
            ["loan.venture.name"] = "Venture debt",
            ["loan.venture.desc"] = "Growth capital that does not touch the cap table. The lender wants to see revenue, and once the schedule starts it does not pause for a bad quarter.",
            ["loan.bond.name"] = "Corporate bond",
            ["loan.bond.desc"] = "A real issuance against a real balance sheet. Cheap money by the standards of this industry, and the size of it means a missed schedule is a public event.",
            ["loan.sovseed.name"] = "State compute grant",
            ["loan.sovseed.desc"] = "A ministry with a budget line and something to prove. A billion, at terms nobody would call generous, on the understanding that the capability stays in the country. Smaller than the full programme and easier to reach, and it costs more for every dollar of it.",
            ["loan.sovereign.name"] = "Sovereign compute programme",
            ["loan.sovereign.desc"] = "A state decides that domestic frontier capability is infrastructure and writes the cheque to prove it. Ten billion now, most of three times that back over eleven years, and a government that will not renegotiate. Nothing else in the game moves this much money, and nothing else fails this loudly.",

            // ---- making the architecture screen legible ----------------------------------------------
            ["arch.strap"] = "Before you build models you can build the thing models are made of. One programme, once, and every model you ship afterwards inherits it: cheaper to run, better for its size, faster to train, or all three. It takes a year and the result is a range rather than a number.",
            ["arch.setting_and_share"] = "{0}   ·   {1} of effort",
            ["arch.cheaper_to_run"] = "{0} cheaper to run than what you have now",
            ["arch.more_from_each"] = "{0} more capability from the same parameters",
            ["arch.faster_runs"] = "{0} faster to train, every run",
            ["arch.cheaper_tokens"] = "{0} cheaper per token once models are live",
            ["arch.points_better"] = "{0} capability on top, before any scale",
            ["arch.no_better"] = "no better than what you already run on",
            ["arch.shape.none"] = "A family aimed at nothing in particular. Spreading the effort evenly is a decision, and it usually produces something no better than the published techniques you already use.",
            ["arch.shape.sparsity"] = "A family built to be cheap to run. Enormous models that only wake part of themselves for each token, so you can serve a size nobody else can afford.",
            ["arch.shape.throughput"] = "A family built for speed of delivery. The same runs finish sooner, so you ship more models a year and can still catch a launch window.",
            ["arch.shape.quality"] = "A family built to be good. Every model it ever produces scores higher for the same compute, which compounds for a decade and shows up in the books last.",
            ["arch.shape.serving"] = "A family built for margin. Nothing a customer can see, and it decides whether you can follow the next price cut somebody else starts.",
            ["arch.shape.reasoning"] = "A family built to think. Capability that does not come from being bigger, which is the only lever left once everybody's clusters are the same size.",

            // ---- what every research node actually is ------------------------------------------------
            ["node.finetuning.desc"] = "Take somebody else's base model and make it do one job well. Every company starts here and none of them stay.",
            ["node.humanfeedback.desc"] = "Teach the model what a good answer looks like instead of hoping. Cuts the odds of a public embarrassment and opens human preference data.",
            ["node.curatedcorpora.desc"] = "Deduplication, filtering and a legal team. Turns a pile of scraped text into something worth training on.",
            ["node.efficientattention.desc"] = "Memory-aware attention kernels and grouped queries. The same model, meaningfully faster to train and cheaper to serve.",
            ["node.series.desc"] = "Ship the next model as a version of the last one instead of as a stranger. The name carries its own audience across, and so does its reputation when it was bad.",
            ["node.coding.desc"] = "Repository scale context, test execution and diffs as training signal. Almost nobody wants this in 2022. By 2025 it is the segment that pays.",
            ["node.conversational.desc"] = "Tone, refusal behaviour and memory across a session. Turns a tool people try into a product people open every morning.",
            ["node.automation.desc"] = "Structured output, long documents and tool calls that a compliance team will sign off. Sells slowly, and then never leaves.",
            ["node.agentic.desc"] = "A model with a machine of its own: a shell, a filesystem and hours of unsupervised work. The most expensive line on the tree and the only one that owns the endgame.",
            ["node.multimodal.desc"] = "Images and audio in, images and audio out. Expensive, and by 2025 buyers stop treating it as a feature and start treating it as the floor.",
            ["node.scalinglaws.desc"] = "Work out precisely how loss falls with parameters and tokens, and stop guessing what a run will produce. Opens hardware you own rather than rent.",
            ["node.mixtureofexperts.desc"] = "Route each token to a fraction of the network. A quarter of the compute per token, and a research org that has to be good enough to keep it stable.",
            ["node.lowprecision.desc"] = "Keep the numbers in eight bits and watch for the run coming apart. Nearly twice the compute out of the same cluster, and a loss curve that can diverge in the last third with nothing to show for the money.",
            ["node.singleprecision.desc"] = "Stop carrying sixty-four bits of mantissa nobody is using. A third more throughput out of the cluster you already rent, for a fortnight of somebody's time.",
            ["node.mixedprecision.desc"] = "Keep the master weights wide and do the arithmetic narrow. Half the memory and close to twice the throughput, for none of the risk that eight bits carries.",
            ["node.dedup.desc"] = "Find the near duplicates, not just the exact ones. The crawl is full of the same page under forty domains, and a run that reads it forty times learns it once and pays forty times.",
            ["node.pipeline_data.desc"] = "Ingest, clean and license text as it appears rather than in a batch once a year. What it buys is a model that knows about this month.",
            ["node.context.desc"] = "Hold an entire codebase or a year of filings at once. This is what makes enterprises stay rather than shop.",
            ["node.licensed.desc"] = "Books, journals and everything else somebody owns. Slow to negotiate, and the quality difference is not subtle.",
            ["node.autonomousagents.desc"] = "The model stops answering and starts doing: calling tools, running loops, finishing tasks nobody watched. The entire agent market runs through this node.",
            ["node.syntheticdata.desc"] = "The open web runs out. From here the model learns from text a model wrote, which works far better than it sounds and only while your model is good enough to write it.",
            ["node.reasoning.desc"] = "Train the model to spend inference thinking. It solves problems nothing else can and the serving bill goes up by a factor of two and a half.",
            ["node.longcontext.desc"] = "Sparsity and a very long window in the same model, without either ruining the other.",
            ["node.datacenter.desc"] = "Power contracts, land, substations and a construction schedule measured in years. The cheapest FLOP in the game sits on the other side of it.",
            ["node.assa1.desc"] = "Automatic Self Safety Auditioning is already running. This licenses a suite of outside algorithms to bolt onto it, and what the licence buys is that the automated passes stop missing the same class of hole every time.",
            ["node.assa2.desc"] = "Every audit the company has ever run is training data now. Enough of it stands up an attacking system the size of the model itself, sealed in with it.",
            ["node.assa3.desc"] = "A standing population of auditors rather than a pass that runs and finishes. Each one specialised, each fed by what the others found, running against every model the company has ever shipped.",
            ["node.red1.desc"] = "The folder of hand-written attacks becomes a machine: it generates its own attempts, keeps the ones that got closest and mutates those.",
            ["node.red2.desc"] = "Long runs with a goal, a budget and a record, aimed at one class of failure at a time. Every failed attempt is kept, because a failed attack is the most useful thing anybody has about the next one.",
            ["node.red3.desc"] = "A standing team of agents that never stops and never ships. They attack every model on sale, all the time, and they get better every time they fail.",
            ["node.data0.desc"] = "User data is pulled out of the model's ordinary working path and kept somewhere it has to ask to reach. This is the difference between leaking a log and leaking a customer list.",
            ["node.data1.desc"] = "Anything sensitive lives encrypted, in a store with its own short access list. It does not stop a breach. It means the breach comes out unreadable.",
            ["node.data2.desc"] = "Training data is processed so no single person can be recovered from what the model learned. The first tier a regulator accepts as an argument rather than as a promise.",
            ["node.data3.desc"] = "Privacy stops being something added after the run and becomes part of how the run works. Half of everything that would have ended the company now does not.",
            ["node.sharding.desc"] = "Adam keeps two moments and a full precision copy of every weight, which is three times the model sitting on every accelerator holding an identical duplicate. Shard them across the cluster and each machine holds its slice.",
            ["node.pipeline.desc"] = "Cut the model into stages and give each machine a stage rather than a copy. The layers no longer have to fit anywhere in particular, only the stage does.",
            ["node.ultrareadiness.desc"] = "A run of this length will lose machines while it is running. Checkpoint often enough to survive it, restart without a human, and hold thousands of accelerators in step for months at a time.",
            ["node.learnedrouting.desc"] = "A sparse model is only as good as the thing deciding which experts see a token. Train the router rather than hashing, balance the load across experts, and stop half the network from never being picked.",
            ["node.expertparallelism.desc"] = "Put each expert on its own machines and route tokens across the fabric to reach them. The model stops having to fit anywhere, and the network becomes the thing you are buying.",
            ["node.fusedkernels.desc"] = "Stop writing intermediate results to memory between every operation. One kernel that does the whole block keeps the arithmetic units fed instead of the memory bus busy.",
            ["node.overlappedcollectives.desc"] = "The cluster spends a large share of every step waiting for gradients to finish moving. Start the next block of arithmetic while they are still in flight and the waiting stops being time.",
            ["node.curriculumtraining.desc"] = "The order tokens arrive in changes what the model gets out of them. Sequence the corpus rather than shuffling it, and raise the difficulty as the model can take it.",
            ["node.selfdistillation.desc"] = "Train the next model against the one you already have as well as against the data. The student reaches the teacher's level for less, and then goes past it.",
            ["node.quantisedserving.desc"] = "Serve at eight bits instead of sixteen. The weights are the same weights, the answers are near enough the same answers, and the machine holds twice as much of it.",
            ["node.speculativedecoding.desc"] = "A small model guesses the next several tokens and the large one checks them all at once. Most guesses are right, and the ones that are not cost nothing to reject.",
            ["node.processsupervision.desc"] = "Reward the working rather than the answer. A model marked only on the final line learns to guess it; one marked on every step learns to get there.",
            ["node.inferencetimesearch.desc"] = "Spend compute when the question is asked rather than only when the model is built. Sample several attempts, score them, keep the best.",
            ["node.hybrid.desc"] = "Attention where it earns its cost and recurrence everywhere else. Long context stops being expensive.",
            ["node.recursive.desc"] = "The models start designing the next models, and the loop closes. Every run after this one is partly written by the run before it.",
            ["node.asi.desc"] = "Beyond this point the company is no longer the most capable thing in the building. Governments will want contracts. The governments that do not will want penalties.",

            // ---- the remaining screens ---------------------------------------------------------------
            ["page.fleet"] = "FLEET",
            ["page.fleet.strap"] = "{0} nameplate, {1} usable. {2} a day to run, {3} a day in value lost.",
            ["page.business"] = "BUSINESS",
            ["page.business.strap"] = "Market rate today is {0} per billion tokens. What you charge against that decides your share; what you give away decides how much of what you serve is worth anything.",
            ["page.team"] = "TEAM",
            ["page.team.strap"] = "{0} of {1} desks in {2}. Payroll {3} a day. Every discipline saturates, so a seventh person in one adds a fraction of what the second did.",
            ["page.team.remote"] = "Plus {0} working remotely.",
            ["page.marketing"] = "MARKETING",
            ["page.marketing.strap"] = "Advertising buys attention, never quality. A product people have not heard of loses to one they have, and a bad product they have heard of gets tried and dropped.",
            ["page.release"] = "RELEASE",
            ["page.release.strap"] = "Finished runs wait here. Waiting costs nothing directly, and costs position every day: market par keeps rising whether or not you ship.",
            ["upgrade.empty.title"] = "NOTHING TO IMPROVE",
            ["upgrade.empty.body"] = "This is where you service a model that is already on sale, without training it again. Nothing is on sale yet, so there is nothing here to work on. Build one first, then come back and keep it current for years.",
            ["upgrade.empty.go"] = "DESIGN A MODEL",
            ["release.empty.title"] = "NOTHING IS WAITING",
            ["release.empty.body"] = "This is where finished models sit before you put them on sale. A training run has to come off the line before there is a decision to make here, and the market gets harder every day you take.",
            ["release.empty.go"] = "DESIGN A MODEL",
            ["page.ranking"] = "RANKING",
            ["page.ranking.strap"] = "Capability, market share and brand, weighted.",
            ["rank.price_and_share"] = "{0}   share {1}",
            ["rank.share"] = "share {0}",
            ["ustrip.kicker"] = "UPGRADE IN PROGRESS",
            ["ustrip.to_level"] = "to level {0}",
            ["ustrip.waiting"] = "waiting for compute",
            ["ustrip.batch"] = "{0} improvements, one job",
            ["panel.researching"] = "RESEARCHING IN PROGRESS",
            ["panel.what_it_opens"] = "WHAT IT OPENS",
            ["panel.team_worth"] = "WHAT THE TEAM IS WORTH",
            ["panel.where_you_work"] = "WHERE YOU WORK",
            ["panel.positions"] = "POSITIONS",
            ["panel.payroll"] = "ON THE PAYROLL",
            ["panel.upgrade_office"] = "UPGRADE THE OFFICE",
            ["panel.service"] = "SERVICE",
            ["panel.reserved_capacity"] = "RESERVED CAPACITY",
            ["panel.day_costs"] = "WHAT THE DAY COSTS",
            ["panel.channels"] = "CHANNELS",
            ["panel.heard_of_you"] = "WHO HAS HEARD OF YOU",
            ["panel.new_campaign"] = "START A NEW CAMPAIGN",
            ["panel.running"] = "RUNNING",
            ["panel.rented_capacity"] = "RENTED CAPACITY",
            ["panel.compute_tiers"] = "COMPUTE TIERS",
            ["panel.owned_hardware"] = "OWNED HARDWARE",
            ["panel.projected"] = "PROJECTED",
            ["panel.pricing"] = "PRICING",
            ["panel.free_tier"] = "FREE TIER",
            ["panel.cluster_split"] = "CLUSTER SPLIT",
            ["panel.what_happened"] = "WHAT HAS HAPPENED",
            ["panel.regulatory"] = "REGULATORY ACTION",
            ["panel.the_office"] = "THE OFFICE",
            ["panel.furnish"] = "FURNISH THE OFFICE",
            ["panel.the_shop"] = "THE SHOP",
            ["panel.company_owns"] = "WHAT THE COMPANY OWNS",
            ["panel.run_finished"] = "THE RUN HAS FINISHED",
            ["rent.meter.capacity"] = "CONTRACTED",
            ["rent.meter.capacity_note"] = "currently {0}",
            ["rent.meter.bill"] = "A DAY",
            ["rent.meter.bill_note"] = "{0} per PF-day",
            ["rent.meter.delivered"] = "DELIVERED",
            ["rent.meter.delivered_note"] = "{0} of what you pay for",
            ["rent.band.caption"] = "THIS MUCH CAPACITY HOLDS ABOUT",
            ["rent.band.nobody"] = "everyday accounts. Nobody is signed up yet, so all of it is idle and all of it is billed.",
            ["rent.band.room"] = "everyday accounts, and you have {0}. There is room.",
            ["rent.band.short"] = "everyday accounts, and you have {0}. They are queueing.",

            // ---- the twenty six explanations the rest of the game was missing ------------------------
            ["tech.revenue.title"] = "REVENUE",
            ["tech.revenue.what"] = "Everything customers paid you this month, before a single bill of yours is taken off. The number on the top line of any company's accounts.",
            ["tech.revenue.affects"] = "Nothing on its own. It funds research, hardware and wages, and a company can grow this number every month while going broke.",
            ["tech.revenue.high"] = "People are using what you built and paying for it. Also the moment your serving bill grows, because every token you sell is a token you have to compute.",
            ["tech.revenue.low"] = "Either nobody has heard of you, or they have and picked somebody else. The two look identical here and completely different on the marketing screen.",
            ["tech.margin.title"] = "MARGIN",
            ["tech.margin.what"] = "What is left of every dollar after you have paid to answer the question. A shop selling at cost has revenue and no margin, and no shop survives on revenue.",
            ["tech.margin.affects"] = "Whether growing is worth doing. At a negative margin every new customer costs you money, so a successful launch is what finishes the company.",
            ["tech.margin.high"] = "You can follow the next price cut somebody starts. Margin is what buys you the right to say yes to a price war.",
            ["tech.margin.low"] = "You are one competitor's price cut away from selling at a loss, and you will find out on the day they announce it.",
            ["tech.tokenprice.title"] = "PRICE PER MILLION TOKENS",
            ["tech.tokenprice.what"] = "A token is roughly three quarters of a word. This is what you charge for a million of them, which is about seven hundred thousand words, or nine copies of a fat novel.",
            ["tech.tokenprice.affects"] = "Revenue per user and how many users stay. The whole industry halves this price roughly every year whether you do or not, so holding still is a price rise.",
            ["tech.tokenprice.high"] = "More money from everybody who stays. Enterprises mind least; consumers leave first and fastest.",
            ["tech.tokenprice.low"] = "You win people who were choosing on price and you serve every one of them out of a margin you just cut. Cheap only works if the model is cheap to run.",
            ["tech.burn.title"] = "WHAT THE DAY COSTS",
            ["tech.burn.what"] = "Everything the company spends between one midnight and the next, whether or not anybody buys anything. Wages, rent, compute, interest.",
            ["tech.burn.affects"] = "How long the money lasts. Cash divided by this is the number of days you have left to be right about something.",
            ["tech.burn.high"] = "A big company moving fast. Also a company that cannot survive one quiet quarter, because none of these bills pause when revenue does.",
            ["tech.burn.low"] = "You can wait, and waiting is a real strategy in this game. It is also a small team training small models while somebody else trains a big one.",
            ["tech.valuation.title"] = "COMPANY VALUATION",
            ["tech.valuation.what"] = "What somebody would pay for the whole company today. Nobody is offering, and it is still the number that decides how much of yourself you give away for money.",
            ["tech.valuation.affects"] = "How expensive a funding round is. Raising ten million against a hundred million valuation costs you a tenth of the company; against a billion it costs a hundredth.",
            ["tech.valuation.high"] = "Money is cheap for you now. This is the moment to raise, and it is exactly when you feel you do not need to.",
            ["tech.valuation.low"] = "Every dollar you raise costs you more of the company. Borrowing starts to look better, which is how companies end up owing more than they are worth.",
            ["tech.equity.title"] = "FOUNDER STAKE",
            ["tech.equity.what"] = "How much of the company is still yours. It starts at all of it and only ever goes down, because a share sold is not a share you can buy back.",
            ["tech.equity.affects"] = "Nothing in the simulation, and everything about what winning means. A company you own a tenth of, that beat everybody, was somebody else's win.",
            ["tech.equity.high"] = "It stayed yours. Usually because you funded growth from revenue, which is slower and is the harder way to play.",
            ["tech.equity.low"] = "You bought speed with ownership. A defensible trade, and the point at which the people who bought the rest start having opinions.",
            ["tech.instalment.title"] = "MONTHLY INSTALMENT AND FEE",
            ["tech.instalment.what"] = "Two different bills wearing the same word. The instalment pays the loan down and stops when it is settled. The fee is rent for holding the loan at all, pays nothing off, and runs even during a payment holiday.",
            ["tech.instalment.affects"] = "The daily burn, from the day the loan lands until the day it is settled. Both are charged whether or not the quarter went well.",
            ["tech.instalment.high"] = "You borrowed a lot, so you can do something big right now. The bill arrives every month for years and does not care what you did with the money.",
            ["tech.instalment.low"] = "Almost nothing owed, which is freedom, and it also means you are building at the speed your own revenue allows.",
            ["tech.petaflop.title"] = "PETAFLOP-DAY",
            ["tech.petaflop.what"] = "The unit training is measured in, the way a builder measures in man-days. One petaflop-day is a machine doing a thousand million million sums a second, for a day.",
            ["tech.petaflop.affects"] = "How long a run takes and what it costs. A model needs a fixed number of these, so twice the fleet is half the wait and the same bill.",
            ["tech.petaflop.high"] = "Runs finish while the idea is still worth having. Compute you are not using is compute you are still paying for.",
            ["tech.petaflop.low"] = "Cheap, and every run takes months. The frontier does not wait for you, and a model that lands a year late lands against next year's competition.",
            ["tech.rentbuy.title"] = "RENT OR OWN",
            ["tech.rentbuy.what"] = "The same choice as a van for your business: hire one by the day and pay more per kilometre, or buy one and carry it whether you drive it or not.",
            ["tech.rentbuy.affects"] = "Cost per petaflop and how fast you can change your mind. Owned hardware is about a third the cost per unit of work and loses roughly a quarter of its value with each new generation.",
            ["tech.rentbuy.high"] = "Owning is the cheapest work in the game, and it is a bet that you will still want this much compute in three years.",
            ["tech.rentbuy.low"] = "Renting costs more per unit and you can stop tomorrow. In a year when the next generation is three times faster, that flexibility was worth every zloty.",
            ["tech.reserved.title"] = "RESERVED CAPACITY",
            ["tech.reserved.what"] = "The difference between a table booked at a restaurant and turning up hoping. Reserved capacity is yours whether anybody else wants it; the shared pool queues when everybody does.",
            ["tech.reserved.affects"] = "How fast your customers get answers when your fleet is busy. Past eighty per cent load a request takes several times longer, and people leave over that before they leave over price.",
            ["tech.reserved.high"] = "Your service stays fast on the day everybody arrives at once, which is usually the day after a good launch.",
            ["tech.reserved.low"] = "You pay less per petaflop and your users find out what a queue feels like exactly when you have most of them.",
            ["tech.split.title"] = "CLUSTER SPLIT",
            ["tech.split.what"] = "One cluster, two jobs. The same accelerators that train a model are the ones answering your users, and a company can do both only by deciding which gets how much.",
            ["tech.split.affects"] = "How fast every long job finishes, and how many tokens you can serve while it runs. Nothing is reserved when nothing is being built: on a quiet week the customers have the whole fleet.",
            ["tech.split.high"] = "Runs and research finish months earlier, which is the only way to be first. Your service slows down for exactly as long as that takes, and people leave over a slow product.",
            ["tech.split.low"] = "Your users get a fast service and you keep the revenue that comes with it, while every programme you have started takes correspondingly longer to land.",
            ["tech.headcount.title"] = "POSITIONS",
            ["tech.headcount.what"] = "How many people can physically work here. A desk is a seat in your office, and you cannot hire the eleventh person into a room with ten desks.",
            ["tech.headcount.affects"] = "Research speed, and the wage bill every single day. The office is what caps this, so growing the team means moving before it means hiring.",
            ["tech.headcount.high"] = "Research moves faster and every one of them is paid on a quiet month too. Ten people are not ten times one; the returns flatten as the room fills.",
            ["tech.headcount.low"] = "Cheap, nimble, and everything takes longer. A founder alone in a garage is a real way to play this and it has a ceiling.",
            ["tech.wage.title"] = "HOURLY WAGE",
            ["tech.wage.what"] = "What you are offering. Every candidate has a private number in their head that they will not go below, and you never get to see it.",
            ["tech.wage.affects"] = "Whether they say yes, and the daily burn forever afterwards. A wage is not a purchase, it is a subscription you have taken out on a person.",
            ["tech.wage.high"] = "They accept immediately and you have set the price of everybody you hire after them.",
            ["tech.wage.low"] = "They refuse, or they accept and you have quietly bought somebody who was worth less than you hoped.",
            ["tech.talent.title"] = "WHAT THE TEAM IS WORTH",
            ["tech.talent.what"] = "Not how many people, but how good. Two brilliant researchers and eight competent ones are a different company from ten competent ones on the same payroll.",
            ["tech.talent.affects"] = "Research points per day and how far a finished model lands from what you were promised on the creator screen.",
            ["tech.talent.high"] = "Runs land near their projection and the tree moves. It is also the most expensive payroll in the game.",
            ["tech.talent.low"] = "Affordable, and your projections become optimism rather than plans. You find that out four months into a run.",
            ["tech.awareness.title"] = "WHO HAS HEARD OF YOU",
            ["tech.awareness.what"] = "The share of each audience that knows your company exists. A shop on a side street with the best bread in the city still sells less than the one on the square.",
            ["tech.awareness.affects"] = "Whether your product is even considered. It never touches how good the product is, so advertising a bad one buys you people who try it once and leave.",
            ["tech.awareness.high"] = "Every launch starts with an audience already waiting. Awareness decays on its own, so this is a tap you keep running, not a wall you build.",
            ["tech.awareness.low"] = "You can ship the best model on the market and watch a worse one outsell it, because people cannot choose something they have never heard of.",
            ["tech.channel.title"] = "CHANNELS",
            ["tech.channel.what"] = "Where the advertising goes. Six of them, and none is best: each reaches a different crowd at a different speed, and what it does to your standing is part of the price.",
            ["tech.channel.affects"] = "Awareness in the audiences that channel favours, and your reputation, up or down. Social is loud, cheap and the only one that can cost you standing.",
            ["tech.channel.high"] = "Three at once cover each other's weak spots. That is the limit, because past three the combination stops meaning anything.",
            ["tech.channel.low"] = "One channel is cheap and reaches one crowd. Perfectly sensible when you know exactly who you are selling to.",
            ["tech.campaign.title"] = "CAMPAIGN LENGTH",
            ["tech.campaign.what"] = "How long you commit for. Longer contracts are cheaper per day and a rolling one costs a quarter more, the way any gym membership works.",
            ["tech.campaign.affects"] = "Cost per day and what you can stop. Awareness fades in weeks, so a campaign that ends is a campaign whose effect ends shortly after.",
            ["tech.campaign.high"] = "Six months at the best rate, paid whatever happens to your revenue in month four.",
            ["tech.campaign.low"] = "You pay the surcharge for being able to walk away, which is worth it in exactly the months you were about to need it.",
            ["tech.par.title"] = "MARKET PAR",
            ["tech.par.what"] = "How good a model has to be to count as normal today. It is not a rule anybody wrote; it is the average of what everybody has already shipped, and it only goes up.",
            ["tech.par.affects"] = "What your model is compared against on the day it goes on sale, not on the day you started training it.",
            ["tech.par.high"] = "A hard market, and a model that beats it is worth a great deal because everybody can see it did.",
            ["tech.par.low"] = "An easy market, briefly. Par rises whether or not you ship, so a finished model sitting on the shelf gets worse every single day.",
            ["tech.shelf.title"] = "WAITING TO RELEASE",
            ["tech.shelf.what"] = "A finished model you have not put on sale yet. It costs nothing to store and it is quietly losing value the whole time.",
            ["tech.shelf.affects"] = "Nothing directly, and your position daily, because market par keeps rising while you think about it.",
            ["tech.shelf.high"] = "Waiting can be right: a launch window, a rival's announcement to dodge, a price to settle first.",
            ["tech.shelf.low"] = "Shipping the day it finishes is usually correct, and it is the option people talk themselves out of.",
            ["tech.capability.title"] = "CAPABILITY",
            ["tech.capability.what"] = "One number for how good a model is, the way a single score stands in for a whole car review. Everybody in this game is measured on the same scale, including you.",
            ["tech.capability.affects"] = "How attractive your product is to every audience, before price and before whether anybody has heard of you.",
            ["tech.capability.high"] = "You are on the frontier. It is also the most expensive place to stand, and standing there does not pay the wages by itself.",
            ["tech.capability.low"] = "You are behind, and behind is survivable: a cheap adequate model sold to people who never needed the frontier is a real business.",
            ["tech.share.title"] = "MARKET SHARE",
            ["tech.share.what"] = "What proportion of the people buying this sort of thing are buying yours. Not how many people you have, but how many of the ones who exist.",
            ["tech.share.affects"] = "Revenue, reputation and how loudly your next launch lands. Share moves over weeks; it never teleports because somebody shipped on Tuesday.",
            ["tech.share.high"] = "People stay with what they already use, so a lead defends itself. It is also a lot of tokens to serve, every day, forever.",
            ["tech.share.low"] = "Room to grow, and the reason nobody is considering you is usually awareness rather than quality.",
            ["tech.points.title"] = "RESEARCH POINTS",
            ["tech.points.what"] = "What understanding is measured in here. Money cannot buy the whole tree: four times the funding buys twice the points, so most of it has to be earned by building things.",
            ["tech.points.affects"] = "Which nodes you can start. Every node costs points and a little cash, and the points are the real gate.",
            ["tech.points.high"] = "The tree opens quickly. It usually means you have been training and shipping, because that is what earns them.",
            ["tech.points.low"] = "A rich company that builds nothing learns nothing, and finds out two years later when the good nodes are still locked.",
            ["tech.era.title"] = "ERAS",
            ["tech.era.what"] = "The tree is laid out on a calendar, not as a shopping list. Era 1 is 2022, era 4 is 2026 onward, and everything is visible from the first day on purpose.",
            ["tech.era.affects"] = "When a node can be started at all. You are meant to see the late game coming and plan the years in between around it.",
            ["tech.era.high"] = "Later eras hold what decides the endgame, and nothing there is reachable without most of what came before it.",
            ["tech.era.low"] = "The early nodes look small and they are what makes everything after them affordable.",
            ["tech.trait.title"] = "MODEL TRAITS",
            ["tech.trait.what"] = "Things you can improve on a model that is already on sale, without training it again. Like servicing a car rather than buying a new one.",
            ["tech.trait.affects"] = "The model's standing in the market and its serving cost. It cannot make a small model into a big one; scale is decided once, at training.",
            ["tech.trait.high"] = "Cheaper and faster than a new run, and it keeps a product current for years past the date it should have aged out.",
            ["tech.trait.low"] = "Upgrading forever does not beat the frontier. At some point somebody trains something you cannot service your way up to.",
            ["tech.traitlevel.title"] = "LEVELS",
            ["tech.traitlevel.what"] = "Each trait can be improved several times, and each step costs more than the one before while giving a little less.",
            ["tech.traitlevel.affects"] = "Cash, compute and calendar. An upgrade programme takes days and shares the fleet with your training runs.",
            ["tech.traitlevel.high"] = "A deeply serviced model beats a newer plain one, right up until it does not.",
            ["tech.traitlevel.low"] = "The first level of anything is the cheapest improvement in the game. Spreading one level across several traits usually beats stacking one.",
            ["tech.pricing.title"] = "PRICING",
            ["tech.pricing.what"] = "What you charge, split between paying by the token and paying a monthly subscription. Most customers only ever see one of the two.",
            ["tech.pricing.affects"] = "Revenue per user, how many stay, and your reputation. Halving your price is liked exactly as much as doubling it is resented.",
            ["tech.pricing.high"] = "More from each customer, and every competitor's price list is one click away from yours.",
            ["tech.pricing.low"] = "You take the people who were choosing on price. Make sure the model is cheap to run first, or you have bought yourself customers at a loss.",
            ["tech.freetier.title"] = "FREE TIER",
            ["tech.freetier.what"] = "How much somebody gets without paying. The free sample at a market stall: it costs you real money and it is how most people ever try anything.",
            ["tech.freetier.affects"] = "Reputation and how many people arrive, against a serving bill for tokens nobody paid for.",
            ["tech.freetier.high"] = "People love you and you are computing an enormous number of answers for nothing.",
            ["tech.freetier.low"] = "Every token is paid for, and a stranger has no way to find out whether your model is any good before deciding.",

