            ["intro.money"] = "Twelve million dollars, no product, and eleven months before the world finds out what any of this is for.",
            ["intro.month"] = "JANUARY 2022",
            ["intro.curiosity"] = "Language models are a research curiosity with a following of maybe ten thousand people.",
            ["intro.unpriced"] = "Nobody outside the field can name one. Nothing has been productised. Nothing has been priced.",
            ["intro.rewritten"] = "In eleven months a chat box will reach a hundred million users and every assumption in this industry will be rewritten twice before 2026.",
            ["intro.you_have"] = "You have twelve million dollars and no product.",
            ["intro.timing"] = "None of the decisions ahead of you can be undone. Most of them are about timing.",
            ["intro.hook"] = "The competition has only just caught the scent of the money. Start while there is still time.",
