            // ---- what the seven founder skills are ---------------------------------------------------
            ["skill.development.title"] = "DEVELOPMENT",
            ["skill.development.what"] = "How well you actually build the thing. Not the idea, the execution: the difference between a plan for a model and a model that came out the way the plan said it would.",
            ["skill.development.affects"] = "How close a finished run lands to the capability the creator projected. Low development means the number you were promised and the number you got are two different numbers.",
            ["skill.development.high"] = "Your projections become plans. Worth most early, when one run is the whole company and a miss is the whole year.",
            ["skill.development.low"] = "Every run is a coin flip around the number on the screen. Survivable if you train often; fatal if you bet everything on one.",
            ["skill.management.title"] = "MANAGEMENT",
            ["skill.management.what"] = "Whether the company wastes money on the way to doing what it does. Every business has a version of this and nobody notices it until the month it matters.",
            ["skill.management.affects"] = "The daily burn, every single day of the campaign. It is the smallest multiplier on this list and the one that runs for fifteen years without stopping.",
            ["skill.management.high"] = "The same company costs less to run. Boring, and it compounds into more runway than any single good decision buys you.",
            ["skill.management.low"] = "You pay a little more for everything, forever. Nothing about it is dramatic, which is exactly why it is easy to leave at the bottom.",
            ["skill.teamwork.title"] = "TEAMWORK",
            ["skill.teamwork.what"] = "How many people you can put in one room before the seventh stops adding anything. Every organisation hits this wall; where it sits is the skill.",
            ["skill.teamwork.affects"] = "How late hiring stops paying. With it low, the fourth person in a discipline is already mostly wasted salary.",
            ["skill.teamwork.high"] = "You can build a real organisation rather than a founder with assistants. It only starts mattering once you can afford ten people.",
            ["skill.teamwork.low"] = "Stay small and stay fast. A perfectly good way to play, and it puts a ceiling on the late game.",
            ["skill.concept.title"] = "CONCEPT",
            ["skill.concept.what"] = "Taste. Knowing which of five directions is worth a year before anybody has evidence either way.",
            ["skill.concept.affects"] = "How much an architecture programme gets out of the same year and the same budget. It is the only skill that touches the level above the model.",
            ["skill.concept.high"] = "Your families come out better than the effort you put in should buy. That difference compounds into every model you ever ship afterwards.",
            ["skill.concept.low"] = "You get roughly what you pay for, which is fine and is also how everybody else plays.",
            ["skill.software.title"] = "SOFTWARE",
            ["skill.software.what"] = "How efficiently the thing runs once it is built. The same model, on the same machines, answering the same questions for less money.",
            ["skill.software.affects"] = "The cost of every token you ever serve. Once you have customers this is a bill that arrives every day and grows with your success.",
            ["skill.software.high"] = "Growing gets cheaper instead of more expensive, which is the difference between scaling and drowning.",
            ["skill.software.low"] = "Every new customer costs you more than the last. Fine while you are small, and it is the reason some labs die from a good launch.",
            ["skill.data.title"] = "DATA ENGINEERING",
            ["skill.data.what"] = "Getting more out of the same text. Cleaning, deduplicating, ordering it, all the unglamorous work that decides how much of a corpus was worth reading.",
            ["skill.data.affects"] = "The effective quality of whatever corpus you own, so a cheap corpus in good hands beats an expensive one in bad ones.",
            ["skill.data.high"] = "You can compete on data you could afford rather than data you could not. Cheapest advantage on this list.",
            ["skill.data.low"] = "You need to buy quality rather than make it, and licensed archives are slow to negotiate and expensive.",
            ["skill.safety.title"] = "SAFETY",
            ["skill.safety.what"] = "Whether you see the problem before the regulator does. Not a moral position, an operational one: knowing what your own model does before somebody else finds out.",
            ["skill.safety.affects"] = "The daily chance of an incident, which is the largest single number in this game. A fine here is not a bad quarter, it is a Tuesday that ends the company.",
            ["skill.safety.high"] = "The thing that ends other people's campaigns mostly does not happen to you. You will never see the disasters you avoided, which is why this is easy to undervalue.",
            ["skill.safety.low"] = "Everything is faster and cheaper until the day it is not. Playable, and it is the single most expensive way to be wrong.",

            // ---- the server room, the racks and the cooling ------------------------------------------
            ["room.title"] = "SERVER ROOM",
            ["compute.power_draw"] = "Drawing {0} kW of {1} kW available.",
            ["compute.over_budget"] = "  OVER BUDGET: capacity is being wasted.",
            ["regulatory.underway"] = "Inspection and clarification underway...   {0} left",
            ["manage.on_sale_now"] = "ON SALE NOW: {0}",
            ["create.in_flight"] = "{0} is in flight: {1} done after {2} days. One at a time.",
            ["create.blurb.branding"] = "Who the company is. The name and the mark go on the product page, the browser tab and the chip, and none of it changes what the model can do.",
            ["create.blurb.foundation"] = "What the model is built on, and what it is called. The family sets the ceiling for everything chosen after it.",
            ["create.blurb.scale"] = "How big it is, and how much it reads. This single trade decides most of the result.",
            ["create.blurb.data"] = "What it learns from. The run draws from the best corpus first, so one good archive lifts the whole mix.",
            ["create.blurb.compute"] = "How much throughput to rent. This buys time and never quality, which is the point.",
            ["create.blurb.safety"] = "What happens when this goes wrong, and how much of the calendar to spend making that less likely. None of it makes a better model.",
            ["create.blurb.review"] = "What the run is projected to produce, and what it costs to find out.",
            ["create.blurb.after"] = "What happens the day it finishes. This can be changed later, and the market will have moved by then.",
            ["create.line_new"] = "New line",
            ["create.new_line_note"] = "A new line stands on its own and starts with nobody using it.",
            ["create.supersedes"] = "Supersedes {0}",
            ["create.supersedes_note"] = "This supersedes whatever {0} currently sells. One line is one product, so the older model stops competing the day this one ships.",
            ["create.cheap_to_serve"] = "Cheap to serve",
            ["create.times_to_serve"] = "{0}x to serve",
            ["create.times"] = "{0}x",
            ["create.needs"] = "Needs {0}",
            ["create.needs_silicon"] = "needs {0} silicon",
            ["create.keep_local"] = "KEEP IT LOCAL",
            ["create.keep_local_note"] = "It finishes onto the shelf and stays there. Train on it, upgrade it, release it the day the market looks right. Holding costs nothing but time.",
            ["create.commercialise"] = "COMMERCIALISE",
            ["create.commercialise_note"] = "It ships the day it finishes. You decide now what a free account gets and what a paid one costs, and both of those decide how many people ever try it.",
            ["create.reach_bought"] = "REACH BOUGHT",
            ["create.free_account_cost"] = "A free account costs you about {0} a month to serve, every month, whether or not it ever pays.",
            ["create.sparse_note"] = "A sparse mixture costs a quarter of the FLOPs per token and a little quality per parameter. On a fixed budget that trade is usually worth taking.",
            ["create.belt_ratio"] = "{0} : 1   (optimum {1})",
            ["create.belt_no_optimum"] = "{0} : 1   (no optimum until you have compute)",
            ["create.training_efficiency"] = "Training efficiency",
            ["create.budget_efficiency"] = "Budget efficiency",
            ["create.cost_to_serve"] = "Cost to serve",
            ["create.memory_used"] = "Memory used",
            ["create.precision_card"] = "{0}x compute, {1}x spread",
            ["create.shape_note"] = "{0}x capability, {1}x to serve",
            ["create.cutoff_today"] = "TODAY",
            ["create.cutoff_back"] = "{0} BACK",
            ["create.cutoff_today_note"] = "Everything up to the day the run starts. Dearest, messiest, and right about the present.",
            ["create.cutoff_old_note"] = "Two years back. Cheap, clean, thoroughly studied, and wrong about anything that has happened since.",
            ["create.cutoff_mid_note"] = "A compromise. Most of the saving, some of the staleness.",
