            ["money.tokens_value"] = "{0} tokens",
            ["money.free_hint"] = "Serving capacity does not care which kind of token it is producing and neither does the bill. A generous tier widens the funnel and can quietly turn most of the fleet into a cost centre.",
            ["money.subscription_hint"] = "A fee you set, decoupled from the market. It protects a good position when prices fall and traps a bad one when they do not.",
