            ["manage.biggest_mover"] = "Today the biggest mover was {0}. Reputation is an opinion and fans are a stock: a bad month can halve the first and barely touch the second.",
            ["manage.unserved"] = "{0} of the addressable market is using nothing at all. That is room to grow into rather than share to take off somebody.",
            ["create.text_bytes"] = "About {0} of text, at roughly four bytes a token.",
            ["create.memory_need"] = "Estimated memory need: {0} GB of {1} GB available",
            ["create.mix_holds"] = "This mix holds {0} and the run wants {1}. Add a source or train on fewer tokens.",
            ["create.sources_enough"] = "{0} sources, enough for this run.",
            ["create.rented_line"] = "Rented capacity: {0}  ({1} units of today's part, {2} usable, {3}/day)",
            ["model.row_line"] = "{0}  ·  capability {1}  ·  {2} days on sale",
            ["news.also_requires"] = "And then {0} on top of it, at {1} a month.",
            ["release.cash_days"] = "{0}   ·   about {1}",
            ["boot.could_not_build"] = "{0} could not be built",
            ["demo.no_market"] = "NO MARKET YET",
            ["demo.nobody_served"] = "Nobody is serving anyone.",
            ["finance.books_start"] = "The books start the first day the company spends or earns anything.",
            ["marketing.floor_note"] = "Being used counts as being known. A company people already have on the service does not become anonymous, so this floor rises with the audience you hold.",
            ["marketing.nothing_booked"] = "Nothing booked. Only the people already using the service have heard of you.",
            ["research.shares_fleet"] = "Research shares the fleet with training, upgrades and family programmes. Free some capacity or rent more and this finishes on its own.",
            ["site.scene_stale"] = "The room exists but the scene has not been rebuilt since it was wired up. Run Scaling Laws, Rebuild scenes.",
            ["site.no_floor_spare"] = "There is no floor to spare here. The sofa, the bench, the rack and the stairs are already touching, and anything else would be standing in the middle of them. Rent a floor and the shop opens.",
            ["team.both_routes"] = "Both routes take two to four days to come back, and both end in the inbox with a wage to agree. What differs is who answers.",
            ["labs.nothing_known"] = "Nothing has happened to them yet that anybody outside the company would know about.",
            ["shelf.scores_today"] = "It scores what it scores from today. Waiting costs nothing directly and costs position every day, because par keeps rising under it.",
            ["hiring.three_ways"] = "Three ways to find somebody, and none of them is best. Contract work is cheap and shallow, the register is slow and free, and a specialist search is expensive and finds exactly who you asked for.",
            ["hiring.register_header"] = "REGIONAL EMPLOYMENT REGISTER  //  DEPARTMENT OF LABOUR AND SOCIAL AFFAIRS\nSECTION IV - PLACEMENT SERVICES FOR TECHNICAL OCCUPATIONS",
            ["hiring.register_notice"] = "NOTICE: Candidate assessments are self-declared under Form E-11/b and have not been independently verified. The Department accepts no liability arising from placement. Processing times of 2-4 working days apply.",
            ["hiring.register_footer"] = "This service is provided free of charge. Standard wages apply. Last updated: 14/03/2009.",
            ["menu.create_company"] = "CREATE YOUR OWN COMPANY",
            ["menu.begin_january"] = "BEGIN, JANUARY 2022",
            ["menu.pick_a_lab"] = "Pick a lab first.",
            ["menu.needs_a_name"] = "Your founder needs a name. It goes on the company page.",
            ["menu.company_name"] = "Company name",
            ["manage.price_note"] = "Price moves standing both ways and it moves it in log space, so halving is liked about as much as doubling is resented. The lever is on the business screen.",
            ["manage.archive_empty"] = "The archive fills the first time a model reaches the market. Runs still on the shelf are not in it, because they were never on sale.",
            ["manage.withdraw_note"] = "Withdrawing it is permanent. The line stops competing, and whatever fleet it was using goes back to everything else.",
            ["create.nothing_else"] = "Nothing else to set. The release screen will be waiting when you want it.",
            ["create.subscription_note"] = "A subscription ignores the market rate, which protects a good position and traps a bad one. Price it high and fewer people ever sign up; price it low and you are serving tokens at a loss the moment the frontier moves.",
            ["create.precision_note"] = "Narrower numbers move more of them through the same cluster. What that costs is not a worse model, it is a less predictable one.",
            ["create.depth_note"] = "Depth is sequential and width is parallel, so the same parameters arranged deep think better and cost more per token, every day, forever.",
            ["create.quality_note"] = "It lands in both terms at once: fewer tokens, worth more each. Whether that pays depends on whether the run had tokens to spare, which the belt on the last stage already answered.",
            ["create.rent_note"] = "Rented capacity is contracted in petaflops, not in boxes, so the bill does not move on its own when the clouds change generation. It never ages, and it bills every day it is held whether or not it is doing anything.",
            ["create.safety_note"] = "Modules stack on what is left rather than adding up, so two at half strength are not one at full. Nothing here can reach certainty, and the protection travels with this model rather than with the company: researching a tier next year does not harden a model shipped today.",
            ["model.design_run"] = "Design a training run from nothing. Months, and the biggest bill the company pays.",
            ["news.strap"] = "Everything that happened, and what somebody will sell you about what happens next.",
            ["room.strap"] = "Four cabinets in a basement. Cheaper per petaflop than anything you can rent, and it comes with the problems physical things have: space, power and heat.",
            ["room.already"] = "You already have one.",
            ["room.cannot_afford"] = "Needs {0} and the company does not have it.",
            ["room.no_such_rack"] = "No cabinet of that kind exists.",
