            ["room.gift_landed"] = "Emil handed over the keys to the basement. Four cabinets, already down there.",
            ["room.bought"] = "The basement under Emil's building is yours. Four cabinets came with it.",
            ["room.locked.title"] = "NO ROOM YET",
            ["room.locked.body"] = "Rented capacity is a slider and a bill. A room is somewhere your own machines live, and it is cheaper per petaflop than anything you can rent because you paid for it once. Emil has a basement under his building with four cabinets already in it.",
            ["room.locked.buy"] = "BUY THE BASEMENT  {0}",
            ["room.locked.gift"] = "Or finish his tour and he gives it to you.",
