            // ---- the world that has opinions about you -----------------------------------------------
            ["loyalty.loose"] = "Looking",
            ["loyalty.open"] = "Open",
            ["loyalty.settled"] = "Settled",
            ["loyalty.committed"] = "Committed",
            ["benefit.sports"] = "Sports card",
            ["benefit.sports.note"] = "The cheapest loyalty in the building. Half the office never uses it and every one of them likes having it.",
            ["benefit.meals"] = "Lunch",
            ["benefit.meals.note"] = "Small, and people notice it every single day, which is what makes it work.",
            ["benefit.transport"] = "Travel card",
            ["benefit.transport.note"] = "Worth most to the people who live furthest away, which is often the people hardest to replace.",
            ["benefit.healthcare"] = "Private healthcare",
            ["benefit.healthcare.note"] = "The one everybody expects and nobody thanks you for. Its absence is what gets noticed.",
            ["benefit.learning"] = "Learning budget",
            ["benefit.learning.note"] = "Cheap for what it buys. It is why researchers stay somewhere that is not paying the most.",
            ["benefit.insurance"] = "Life and disability cover",
            ["benefit.insurance.note"] = "Dull, expensive, and the one people actually stay for once they have families.",
            ["benefits.title"] = "WHAT YOU OFFER BEYOND THE SALARY",
            ["benefits.strap"] = "Charged for every person on the payroll, every month, including the ones who never use it. That is what makes it a decision.",
            ["benefits.per_head"] = "{0} per person a month",
            ["benefits.everybody"] = "{0} a month for all {1}",
            ["benefits.total"] = "{0} a month for {1} people",
            ["benefits.loyalty"] = "+{0} loyalty",
            ["benefits.none"] = "Nothing offered. Nobody is leaving over it yet.",
            ["benefits.average"] = "AVERAGE LOYALTY",
            ["relation.friendly"] = "Friendly",
            ["relation.neutral"] = "Neutral",
            ["relation.tense"] = "Tense",
            ["relation.hostile"] = "Hostile",
            ["relation.rivalry"] = "Rivalry",
            ["relation.friendly.note"] = "They would take the call, and they might say yes.",
            ["relation.neutral.note"] = "Competitive and professional. Nothing has happened between you.",
            ["relation.tense.note"] = "Cooling. Something has happened and something else is going to.",
            ["relation.hostile.note"] = "Competing against your interests on purpose.",
            ["relation.rivalry.note"] = "Actively looking for a way to cost you something.",
            ["relation.title"] = "HOW THEY SEE YOU",
            ["labtrait.title"] = "WHAT THEY ARE LIKE",
            ["labtrait.fearless"] = "Fearless",
            ["labtrait.fearless_note"] = "Ships the biggest thing it can afford the day it can afford it. It will be first more often than it should be, and it will be wrong in public when it is wrong.",
            ["labtrait.patient"] = "Patient",
            ["labtrait.patient_note"] = "Waits for the next generation of silicon and then steps over everybody. Quiet for a year at a time, and the year it stops being quiet is the one that costs you.",
            ["labtrait.undercutting"] = "Undercutting",
            ["labtrait.undercutting_note"] = "Wins on price. Whatever you charge, they charge less, and they are content to earn nothing on a customer you were counting on.",
            ["labtrait.open"] = "Open handed",
            ["labtrait.open_note"] = "Gives the weights away and takes the reach instead of the margin. Hard to out-price and impossible to out-distribute.",
            ["labtrait.institutional"] = "Institutional",
            ["labtrait.institutional_note"] = "Sells to institutions rather than to people. Slower to move, far harder to dislodge once it is inside somewhere.",
            ["labtrait.deep"] = "Deep pockets",
            ["labtrait.deep_note"] = "Money behind it that its own revenue does not explain. It can lose for longer than you can.",
            ["labtrait.expanding"] = "Expanding",
            ["labtrait.expanding_note"] = "Opening everywhere at once. Every office it opens is a market it is in and you are not.",
            ["labtrait.wobbling"] = "Wobbling",
            ["labtrait.wobbling_note"] = "Publicly in trouble. Still trading, no longer setting the pace, and worth watching for what it does when it stops being able to pay for what it promised.",
            ["labtrait.absorbed"] = "Absorbed",
            ["labtrait.absorbed_note"] = "The people and the models went somewhere larger. The name may still be on the door.",
            ["labtrait.hostile"] = "Hostile",
            ["labtrait.hostile_note"] = "Competing against your interests on purpose rather than as a side effect of competing.",
            ["labtrait.veteran"] = "Veteran",
            ["labtrait.veteran_note"] = "Was working on this before there was a market to work on it for. Knows where the bodies are buried, including some of its own.",
            ["labtrait.newcomer"] = "Newcomer",
            ["labtrait.newcomer_note"] = "Started after the race did. Everything it has, it built in public and in a hurry.",
            ["labtrait.scarred"] = "Scarred",
            ["labtrait.scarred_note"] = "Has been through something public and is still trading. Whatever it was they survived it, and companies that survive one usually see the next one coming.",
            ["labtrait.leading"] = "Leading",
            ["labtrait.leading_note"] = "The best thing on the market today is theirs, and clearly enough that nobody is arguing. Whatever you are planning, this is the number it has to beat.",
            ["labtrait.quiet"] = "Quiet",
            ["labtrait.quiet_note"] = "Has shipped nothing in a long time. Either something large is coming, or something has gone wrong in a building nobody can see into.",
            ["relation.history"] = "WHAT HAPPENED",
            ["relation.nothing"] = "Nothing has happened between you yet.",
            ["relation.reason.poached"] = "You took {0} off their payroll.",
            ["relation.reason.reported"] = "They found out you had approached {0}.",
            ["relation.reason.apologised"] = "You apologised for the approach.",
            ["relation.reason.hungup"] = "You hung up on them.",
            ["effect.viral"] = "Viral",
            ["effect.viral.note"] = "More people are arriving than the product explains. It will not last.",
            ["effect.viral.news"] = "Something about {0} caught. People are arriving faster than anything explains.",
            ["effect.first"] = "New lab",
            ["effect.first.note"] = "People are looking because you are new. You get this once.",
            ["effect.first.news"] = "A new lab always gets looked at. Clean slate, and you get it once.",
            ["effect.harbour"] = "Safe harbour",
            ["effect.harbour.note"] = "A year with nothing going wrong. People trust you with their data.",
            ["effect.harbour.earned"] = "A year with no penalty and no scandal. People have started trusting you with their data.",
            ["effect.harbour.lost"] = "Twelve months of trust, gone in an afternoon.",
            ["effect.backlash"] = "Backlash",
            ["effect.backlash.note"] = "Something went wrong in public and people are leaving over it.",
            ["effect.campaign"] = "Campaign",
            ["effect.campaign.note"] = "A campaign is running. It is getting louder out there.",
            ["effect.days_left"] = "{0} days left",
            ["world.source"] = "THE WIRE",
            ["world.chipsact.head"] = "Fifty two billion aimed at building fabs at home",
            ["world.chipsact.body"] = "Public money, and none of it makes a wafer this year. Everything on this list so far has made silicon harder to get; this is the first thing pointing the other way, and it will take four years to arrive.",
            ["world.researchweights.head"] = "A strong model is handed to researchers on a form",
            ["world.researchweights.body"] = "Access by application, weights included, on the understanding that nobody would pass them on. That understanding lasts a week.",
            ["world.frontierjump.head"] = "The model everybody upgrades for",
            ["world.frontierjump.body"] = "Not a cheaper token and not a wider funnel. A reason for people who tried this once, decided it was a toy, and left, to come back and look again.",
            ["world.pauseletter.head"] = "Thousands sign a letter asking everyone to stop for six months",
            ["world.pauseletter.body"] = "Nobody stops. What changes is that for a season every buyer wants to know whether the thing they are about to depend on was built carefully.",
            ["world.nationalblock.head"] = "A country switches an assistant off inside its borders",
            ["world.nationalblock.body"] = "A regulator, a data protection complaint, and a service that simply stops answering for a whole country. The first time anybody found out this could be taken away.",
            ["world.devday.head"] = "The second big price cut of the year, from a stage",
            ["world.devday.body"] = "Whatever margin was left on a token after the spring went here. Selling tokens is now a volume business whether or not anybody planned for that.",
            ["world.boardcrisis.head"] = "A board removes its chief executive and takes him back in five days",
            ["world.boardcrisis.body"] = "Nothing about the technology changed. Everybody who had built on it spent a week working out what they would do if the company simply stopped existing on a Friday.",
            ["world.openagain.head"] = "Stronger open weights, and nobody is surprised any more",
            ["world.openagain.body"] = "The third time in eighteen months. What used to be an event is now a release schedule, and the floor under the price sinks with it.",
            ["world.vetoed.head"] = "A safety bill passes both houses and is vetoed",
            ["world.vetoed.body"] = "The paperwork everybody had started budgeting for does not arrive. Worth noticing precisely because it is the one time in this decade that a regime went the other way.",
            ["world.parissummit.head"] = "The third summit, and safety is no longer in its name",
            ["world.parissummit.body"] = "Two years ago the room was worried about what this could do. This year it is worried about who is going to own it.",
            ["world.projection"] = "Projection. This is where the game expects things to go, not something that has been announced.",
            ["world.ukraine.head"] = "War closes a supply line nobody thinks about",
            ["world.ukraine.body"] = "A large share of the purified neon the world's chip lithography runs on came out of one country, and it has stopped. Nobody buys neon; everybody buys what neon makes.",
            ["world.shanghai.head"] = "The city that assembles the world stops for two months",
            ["world.shanghai.body"] = "A hard lockdown across the largest electronics manufacturing region on earth. Orders placed this quarter arrive next quarter, and the ones already placed are somewhere on a ship.",
            ["world.openweights.head"] = "A capable model is published with its weights",
            ["world.openweights.body"] = "For the first time anybody can download something good and run it themselves. Every price list in the industry now has a free alternative sitting underneath it.",
            ["world.embargo.head"] = "Export controls land on the best accelerators",
            ["world.embargo.body"] = "The fastest silicon can no longer be sold into the largest market for it. Demand does not go away when supply is redirected; it goes somewhere else, and that somewhere is the queue you are standing in.",
            ["world.chatlaunch.head"] = "A chat assistant goes public and the world notices",
            ["world.chatlaunch.body"] = "Nothing about the technology changed this week. What changed is that people who had never heard the words now want to use it, all at once, and a market that took a decade to imagine arrived in five days.  The lab behind it is not making money on this. It does not have to.",
            ["world.searchrace.head"] = "The two largest software companies put assistants in search",
            ["world.searchrace.body"] = "Within a day of each other. Whatever accelerators were going spare last month are now committed for the next two years.",
            ["world.apicut.head"] = "An order of magnitude comes off the going rate",
            ["world.apicut.body"] = "One announcement, and what a million tokens costs is a tenth of what it was. Everybody selling tokens now has to explain why theirs are worth more.",
            ["world.weightsleak.head"] = "Frontier weights escape onto the open internet",
            ["world.weightsleak.body"] = "Released to researchers on a form, on a torrent within the week. The floor under the price of a token stops being theoretical.",
            ["world.openlicence.head"] = "Open weights arrive with a commercial licence",
            ["world.openlicence.body"] = "The same again, deliberately this time, and with permission to build a business on it. The cheapest competitor in your market now costs nothing and never sends an invoice.",
            ["world.summit.head"] = "Governments agree that somebody should be checking",
            ["world.summit.body"] = "A declaration rather than a law, signed by enough countries to matter. Evaluation stops being a research interest and starts being something a buyer asks for.",
            ["world.copyright.head"] = "A newspaper sues over what the models were trained on",
            ["world.copyright.body"] = "Every corpus in the industry is now a question somebody might have to answer in court, and buyers have started asking where the data came from before they ask what it can do.",
            ["world.aiact.head"] = "The first comprehensive regime passes",
            ["world.aiact.body"] = "Documentation, evaluation and a paper trail before a release rather than after it. None of it makes a model better and all of it takes calendar, which is the one thing this business cannot buy back.",
            ["world.picksandshovels.head"] = "The company selling the shovels is now the most valuable",
            ["world.picksandshovels.body"] = "More valuable than any of the companies buying from it. Worth sitting with for a moment if you have been wondering who is actually winning this.",
            ["world.reasoning.head"] = "Models start thinking before they answer",
            ["world.reasoning.body"] = "Spending compute at the moment of the question rather than only at training time. The same silicon suddenly buys more, which is the first good news the supply side has had in two years.",
            ["world.nuclear.head"] = "A datacenter restarts a nuclear plant to feed itself",
            ["world.nuclear.body"] = "The grid is being rebuilt, and it is not being rebuilt for people running four cabinets in a basement. Expect the small tariff to notice.",
            ["world.cheapmodel.head"] = "A model trained for a fraction of the price matches the expensive ones",
            ["world.cheapmodel.body"] = "Not a better model. A model that is roughly as good and cost roughly nothing, which is worse news for everybody selling one. The going rate is following it down and it is not coming back up.",
            ["world.stargate.head"] = "Half a trillion dollars of compute is announced",
            ["world.stargate.body"] = "Announced, not built. But everybody who supplies an accelerator has read the same press release and adjusted their order book accordingly.",
            ["world.selloff.head"] = "The market works out that efficiency is not demand",
            ["world.selloff.body"] = "A fifth off the most valuable company in the world in a single session, on the theory that if models get cheap the shovels stop selling. The theory is wrong, and it will take a year for that to be obvious.",
            ["world.gpai.head"] = "Obligations for general purpose models start applying",
            ["world.gpai.body"] = "The part of the regime that was two years away is now this quarter's problem, and it lands hardest on whoever has the least paperwork already written.",
            ["world.datawall.head"] = "The public internet runs out of good text",
            ["world.datawall.body"] = "Not all text. Text worth training on. From here a corpus is something made rather than something found, and making it costs compute that used to go into the model.",
            ["world.liquidcooling.head"] = "Liquid cooling stops being exotic",
            ["world.liquidcooling.body"] = "Standard parts, ordinary suppliers, and a rack that holds far more than it used to. The cheapest capacity increase in years, and it arrives for everybody at once.",
            ["world.braindrain.head"] = "The researchers leave for smaller rooms",
            ["world.braindrain.body"] = "Enough of them, at once, that the pace visibly slows. What one of them is worth has gone up and it is not coming down while there is somewhere else to go.",
            ["world.agents.head"] = "Agents start doing the work rather than describing it",
            ["world.agents.body"] = "Demand of a kind this market has not seen: not people asking questions, but software running for hours on somebody's behalf. Enormous, and utterly unforgiving about response times.",
            ["effect.pulling"] = "Pulling demand {0} right now.",
            ["effect.about"] = "~{0}",
            ["effect.roughly_left"] = "Roughly {0} left, as far as anybody here can tell.",
            ["effect.open_ended"] = "Open ended. It runs until you cancel it, and it bills every day it does.",
            ["effect.booked_left"] = "Booked for another {0}.",
