            ["intel.benefits.show"] = "SEE BENEFITS",
            ["intel.benefits.hide"] = "HIDE BENEFITS",
            ["intel.benefits.press"] = "You will not miss an event again. Hardware launches, regulatory moves and rival releases reach you while there is still time to act on them, rather than in the same week everybody else finds out. Cheap, wide, and wrong often enough that you have to think about what you read.",
            ["intel.benefits.known"] = "What is happening inside the other labs, rather than what they announced. Who is hiring, who is quietly falling behind, which company is one bad quarter from being bought. The board tells you where a rival stands today; this tells you where they are heading.",
            ["intel.benefits.trend"] = "A weak generation has broken more than one company that had already committed to it. An expert group reads the silicon roadmap months out, so you can wait for the part that is worth buying instead of buying the part that shipped.",
            ["phone.menu.title"] = "PHONE",
