            ["phone.ask.business"] = "How is business going?",
            ["phone.emil.resume"] = "Right, let us carry on.",
            ["phone.emil.good"] = "Honestly? Better than it has any right to be. We are up on the quarter and I am number {0} on the board, which my accountant keeps telling me is not a personality. How about you?",
            ["phone.emil.steady"] = "Same as ever. Number {0}, invoices going out, nobody writing about us. It is not exciting but it pays for the office. You?",
            ["phone.emil.bad"] = "Do not ask. We are down on the quarter and I am number {0}, which is further down than I want to say out loud. It will turn. It usually turns.",
