            // ---- premises -----------------------------------------------------------------------
            ["office.house.name"] = "House",
            ["office.house.desc"] = "The room you started in. There is nowhere for a second person to sit, so everything that gets built here gets built by you.",
            ["office.loft.name"] = "Small office hub",
            ["office.loft.desc"] = "Ten desks and a lease. The first month the company is somewhere rather than somebody.",
            ["office.floor.name"] = "Big company hub",
            ["office.floor.desc"] = "Twenty desks, a proper server closet, and the first month anybody has to ask who owns something.",
            ["office.campus.name"] = "Campus",
            ["office.campus.desc"] = "Purpose built, well equipped, and expensive enough that the rent shows up in the monthly numbers whether or not the desks are full.",
            ["office.tower.name"] = "Tower floor",
            ["office.tower.desc"] = "Two floors of a building with your name in the lobby. The rent is a number the board asks about, and the desks fill faster than anybody plans for.",
            ["office.multisite.name"] = "Multiple sites",
            ["office.multisite.desc"] = "Three time zones and a travel budget. More people than any one room can hold, at the price of nobody being in the same room.",
