            ["walk.stop"] = "Stop the walkthrough",
            ["walk.room.title"] = "The server room",
            ["walk.room.blurb"] = "Buying a cabinet, standing it on the floor and putting cards in it.",
            ["walk.room.open"] = "Right, the basement. Everything you need is on this rail down the side. Nothing here bills you until you buy something, so have a look first.",
            ["walk.room.shop"] = "These are the cabinets. The cheap one is an open frame: fine now, and it cooks the moment the cards get hot. The dearer ones take more heat before they start throttling.",
            ["walk.room.buy"] = "Pick one and buy it. It goes into the store room, not onto the floor, so you can still change your mind about where it stands.",
            ["walk.room.carry"] = "You are carrying it now. The squares that will take it are lit up.",
            ["walk.room.stand"] = "Put it down anywhere. You can slide it later for nothing, so do not agonise over it.",
            ["walk.room.open_rack"] = "Now click the cabinet itself. That opens it up so you can see what is inside.",
            ["walk.room.fit"] = "Every slot takes a card or a fan. Cards make compute, fans stop it throttling. Put something in.",
            ["walk.room.done"] = "That is it. It is your own machine now, so no rent on this bit ever again. Watch the heat, and come back when the cards start getting old.",
            ["guide.step.compute_cap"] = "Listen, for now keep the server rent under $80,000. Seriously, write it down. And once we are through the business side, I have something for you that will get you off renting altogether.",
            ["walk.chip.kicker"] = "GUIDE",
            ["walk.chip.call"] = "call Emil",
            ["phone.menu.messenger"] = "Messager dIn",
            ["phone.day"] = "Day {0}",
            ["phone.thread.empty"] = "Nothing here yet. Write to him.",
            ["phone.compose.write"] = "Write / Call",
            ["phone.compose.guides"] = "HE CAN WALK YOU THROUGH",
            ["phone.ask.guide"] = "Can you walk me through it? {0}",
            ["phone.guide.now"] = "I can show you now if you have a minute. Say the word and we go through it together, step by step.",
            ["phone.guide.yes"] = "Yes, show me now",
            ["phone.guide.later"] = "Not right now",
            ["phone.guide.no"] = "Not right now, I'll get back to you.",
            ["creator.click_map"] = "Click anywhere on the map to choose a region, or click one of the sixteen countries to settle it in one go.",
            ["creator.pick_country_hint"] = "Pick a country from the map or from this list.",
            ["research.era.5"] = "ERA 5   STATECRAFT   2029 ONWARD",
            ["sector.bureaucracy"] = "Bureaucracy",
            ["sector.bureaucracy.blurb"] = "Permits, benefits, tax filings, land registry. Nobody loves it and nobody notices it working, which makes it the one sector where a mistake is survivable.",
            ["sector.education"] = "Education",
            ["sector.education.blurb"] = "Curriculum, assessment, where the teachers go. Slow to show results and slower to show damage, which cuts both ways.",
            ["sector.health"] = "Health",
            ["sector.health.blurb"] = "Triage, rotas, epidemiology, what the hospitals order next month. The first sector where being wrong is counted in people.",
            ["sector.logistics"] = "Logistics",
            ["sector.logistics.blurb"] = "Freight, ports, the power grid's schedule. The largest continuous workload a country has, and it fails in public within hours.",
            ["sector.economy"] = "Economy",
            ["sector.economy.blurb"] = "Fiscal modelling and the central bank's forecast. Your models start deciding what money is worth next quarter.",
            ["sector.security"] = "National security",
            ["sector.security.blurb"] = "Policing, fraud, borders. Enormous money, and the first sector where a failure is a scandal about the company rather than about the state.",
            ["sector.diplomacy"] = "Diplomacy",
            ["sector.diplomacy.blurb"] = "Treaty drafting, negotiation modelling, what to say and when. Discreet, extremely well paid, and impossible to explain afterwards.",
            ["sector.defence"] = "Defence",
            ["sector.defence.blurb"] = "Doctrine, procurement, threat assessment. The largest fee in the game and the only sector whose failure has been known to end the company that took it.",
            ["state.already_signed"] = "Already signed.",
            ["state.not_signed"] = "No contract yet.",
            ["state.needs_liaison"] = "Needs {0} first. Nobody signs a national contract with a company they have not been auditing.",
            ["state.needs_record"] = "Your five-year safety record reads {0}. They want {1}, and waiting is the only way to get there.",
            ["state.sector_running"] = "Already running.",
            ["state.sector_not_running"] = "That sector is not running.",
            ["state.needs_sector"] = "Needs {0} running first.",
            ["state.needs_points"] = "Needs {0} research points. You have {1}.",
            ["state.needs_cash"] = "Needs {0} to set up.",
            ["state.sector_holds_up"] = "{0} is running on top of it. Hand that back first.",
            ["state.signed.story"] = "The government of {0} has signed a national programme. The company's models will be run inside the state's own systems.",
            ["state.sector.story"] = "{0} is now running on the company's models, at {1} a day.",
            ["state.handed_back.story"] = "The company has handed {0} back to the state.",
            ["state.failure.story"] = "{0} failed nationwide. The company has been billed {1}.",
            ["state.title"] = "STATE PROGRAMME",
            ["state.strap"] = "Running parts of a country on your own models. The largest money in the game and the only mistakes measured in billions.",
            ["state.record"] = "FIVE-YEAR SAFETY RECORD",
            ["state.record.note"] = "What a government sees when it looks you up. Money cannot move this one.",
            ["state.sign"] = "SIGN THE PROGRAMME",
            ["state.signed_with"] = "Signed with {0}, day {1}",
            ["state.delivery"] = "DELIVERY",
            ["state.delivery.note"] = "How much of what you promised the fleet is actually covering. The state pays this share of the fee, and everything below full makes a failure more likely.",
            ["state.risk"] = "FAILURE RISK TODAY",
            ["state.held"] = "HELD FOR THE STATE",
            ["state.held.note"] = "Capacity the paying public no longer has. It comes off the top, before training and before customers.",
            ["state.fee"] = "FEE",
            ["state.power"] = "POWER",
            ["state.failure_cost"] = "IF IT FAILS",
            ["state.on_notice"] = "ON NOTICE. Your record has fallen below what they signed for, and the risk is doubled while it stays there.",
            ["state.failures_so_far"] = "{0} failures, {1} paid out",
            ["state.start"] = "TAKE IT ON",
            ["state.stop"] = "HAND IT BACK",
            ["state.locked"] = "LOCKED",
            ["state.running"] = "RUNNING",
            ["state.everything"] = "All eight would pay {0} a day and hold {1} PF. The failure weights add up faster than the fees do.",
            ["biz.company_marketing"] = "COMPANY MARKETING",
            ["biz.company_marketing.blurb"] = "Reputation, slowly, and it survives a model going out of date.",
            ["biz.model_marketing"] = "MODEL MARKETING",
            ["biz.model_marketing.blurb"] = "Attention on the current flagship. It stops working the day the invoices stop.",
            ["biz.benefits"] = "STAFF BENEFITS",
            ["biz.running"] = "running",
            ["biz.nothing_running"] = "nothing running",
            ["biz.offering"] = "{0} offered",
            ["biz.offering_none"] = "nothing offered",
            ["biz.a_day"] = " a day",
            ["biz.per_person_a_month"] = " per person, a month",
            ["biz.open"] = "OPEN",
            ["biz.close"] = "CLOSE",
            ["common.the_founder"] = "The founder",
            ["room.back"] = "BACK TO THE OFFICE",
            ["plate.ceo_of"] = "CEO of {0}",
            ["build.title"] = "FURNISH",
            ["build.done"] = "DONE",
            ["build.open"] = "FURNISH THE OFFICE",
            ["build.shop"] = "BUY",
            ["build.store"] = "IN STORAGE",
            ["build.store_empty"] = "Nothing in storage.",
            ["build.carrying"] = "Left click a lit square to put it down. Right click anywhere to put it in storage.",
            ["build.stash"] = "PUT IN STORAGE",
            ["build.sell"] = "SELL {0}",
            ["build.seats"] = "{0} desks",
            ["build.no_floor"] = "This office has no open floor to furnish.",
            ["build.hint"] = "Right click a piece to pick it up, left click a lit square to put it down.",
            ["bank.worth"] = "WHAT THE COMPANY IS WORTH",
            ["bank.cash"] = "Cash in the bank",
            ["bank.hardware"] = "Hardware, at what it would fetch today",
            ["bank.property"] = "Property owned outright",
            ["bank.furniture"] = "Furniture, at resale",
            ["bank.valuation"] = "COMPANY VALUATION",
            ["bank.book_value"] = "{0} of that is things you own. The rest is what somebody thinks you will build.",
            ["bank.run_rate"] = "Annual revenue run rate",
            ["bank.founder_stake"] = "Founder stake worth",
            ["plate.off_duty"] = "{0}, in at {1}:00",
            ["research.operations"] = "OPERATIONS",
            ["node.racktelemetry"] = "Rack telemetry",
            ["node.racktelemetry.desc"] = "Inlet and outlet probes on every cabinet, logged, so the room stops being a thing you find out about when the throughput drops. What one more card would do to a cabinet is arithmetic somebody has already done; this is putting it on the panel before the card is fitted rather than after.",
            ["node.airflow"] = "Airflow modelling",
            ["node.airflow.desc"] = "Simulate the room rather than the cabinet: where the cold aisle actually goes, which vents are fighting each other, and how much of the extract is recirculated warm air that never left. Every cabinet on the floor sheds a little more for it.",
            ["node.liquidloops"] = "Liquid loops",
            ["node.liquidloops.desc"] = "Plumbing, pumps and a heat rejection loop for the immersion tanks. Air runs out long before the silicon does, and a tank that is properly served stops caring how hot this year's accelerator runs.",
            ["node.substation"] = "Own substation",
            ["node.substation.desc"] = "The room stops being on the household meter. A transformer, a metered industrial connection and the paperwork that goes with drawing that much power in a residential street.",
            ["node.agi"] = "General intelligence",
            ["node.agi.desc"] = "Not a better model. A model that does not need to be told what kind of problem it is looking at. Everything after this is about what you point it at.",
            ["node.assimilation"] = "Real-time assimilation",
            ["node.assimilation.desc"] = "Reading a country as it happens: every transaction, every shipment, every filing, as one continuous input rather than as a report that arrives on Friday.",
            ["node.liaison"] = "Sovereign liaison",
            ["node.liaison.desc"] = "Clearances, a permanent office, and somebody whose whole job is the government's phone number. Nobody signs a national contract with a company they have not been auditing for years.",
            ["node.oversight"] = "Continuous oversight",
            ["node.oversight.desc"] = "A second model whose only job is watching the first one, on the sectors that matter, without ever being the one making the decision.",
            ["node.redundant"] = "Redundant inference",
            ["node.redundant.desc"] = "The state's workload runs on two independent paths so a shortfall degrades instead of stopping. Costs capacity to have and saves the company when it runs out.",
            ["rack.next_card"] = "ONE MORE CARD",
            ["rack.next_reading"] = "{0}, {1} of full speed",
            ["rack.next_full"] = "No slot free",
            ["create.corpus_market"] = "ALSO ON THE MARKET",
            ["create.corpus_offer"] = "{0} tokens, quality {1}",
            ["create.panel.what_for"] = "WHAT IS IT FOR",
            ["create.panel.free_tier"] = "FREE TIER",
            ["create.panel.subscription"] = "SUBSCRIPTION",
            ["create.panel.readout"] = "SCALING READOUT",
            ["create.panel.notes"] = "NOTES",
            ["create.panel.precision"] = "PRECISION",
            ["create.panel.arrangement"] = "ARRANGEMENT",
            ["create.panel.dedup"] = "DEDUPLICATION",
            ["create.panel.compute"] = "COMPUTE",
            ["create.panel.projection"] = "PROJECTION",
            ["create.back"] = "BACK",
            ["create.corpus_toggle"] = "{0}  ({1} tokens, quality {2})",
            ["width.fp64"] = "FP64",
            ["width.fp64.pitch"] = "Double width. Nobody trains like this any more, which is exactly why it is what you are left with before you have researched anything. Slow, and it never lies to you about where the run will land.",
            ["width.fp32"] = "FP32",
            ["width.fp32.pitch"] = "Full width. A third more through the same silicon than double, and still no drama in the loss curve.",
            ["width.bf16"] = "BF16",
            ["width.bf16.pitch"] = "What everybody trains in. Close to twice the throughput of full width, for none of the risk that eight bits carries.",
            ["width.fp8"] = "FP8",
            ["width.fp8.pitch"] = "Eight bits. Nearly twice the compute out of the same cluster, and a run that can come apart in the last third with nothing to show for the money.",
            ["width.fp8.warning"] = "Needs 2023 silicon. The spread on the finished model is more than twice what it would be at BF16, so this is a bet, not a saving.",
            ["shape.deep"] = "Deep",
            ["shape.deep.pitch"] = "Many thin layers. Reasons in more steps and each step waits for the last one.",
            ["shape.deep.note"] = "Better per parameter, dearer per token, and the latency shows under load.",
            ["shape.balanced"] = "Balanced",
            ["shape.balanced.pitch"] = "The proportions everything else in the game is measured against.",
            ["shape.balanced.note"] = "Exactly neutral. Nothing about the rest of the run changes.",
            ["shape.wide"] = "Wide",
            ["shape.wide.pitch"] = "Few fat layers. Less depth to reason through, and the whole thing parallelises.",
            ["shape.wide.note"] = "Cheaper to serve than anything else at the same size, which is what pays when the audience is large and price sensitive.",
            ["dedup.raw"] = "Raw",
            ["dedup.raw.pitch"] = "Everything the crawl found, repeats included.",
            ["dedup.raw.note"] = "The most tokens for the money and the model spends some of them learning the same page nine times.",
            ["dedup.standard"] = "Standard",
            ["dedup.standard.pitch"] = "Exact duplicates removed. What a competent team does without being asked.",
            ["dedup.standard.note"] = "Neutral. This is the baseline the corpus quality figures assume.",
            ["dedup.aggressive"] = "Aggressive",
            ["dedup.aggressive.pitch"] = "Near duplicates too, and the boilerplate. Costs a fifth of the corpus.",
            ["dedup.aggressive.note"] = "Worth it when the corpus is larger than the run needs, and a waste of a fifth of it when it is not.",
            ["plan.no_corpus"] = "no usable data sources selected",
            ["plan.needs_memory"] = "needs {0} GB of accelerator memory, fleet offers {1} GB",
            ["plan.no_compute"] = "the fleet has no usable compute",
            ["hosting.growth"] = "Growth cluster",
            ["hosting.growth.pitch"] = "Reserved capacity for about a million everyday accounts. Holds its speed while the shared pool starts to queue.",
            ["hosting.edge"] = "Edge tier",
            ["hosting.edge.pitch"] = "Half the capacity at the same money, and it barely slows down at all. For products sold on being fast rather than on being big.",
            ["hosting.bulk"] = "Bulk allocation",
            ["hosting.bulk.pitch"] = "Three times the capacity for twice the money, on shared iron. It queues under load like everything else in the pool, and at this size it will.",
            ["channel.social"] = "Social",
            ["channel.social.pitch"] = "Cheap, immediate and it forgets you just as fast. It can go further than anything else here or nowhere at all, and it is the only channel that can cost you standing.",
            ["channel.press"] = "Press",
            ["channel.press.pitch"] = "Barely moves the numbers and is the one thing that reliably builds standing. Enterprise buyers read it; nobody else does.",
            ["channel.radio"] = "Radio",
            ["channel.radio.pitch"] = "Regional, steady and unfashionable. Cheap for what it covers and it keeps working long after the money stops.",
            ["channel.tv"] = "Television",
            ["channel.tv.pitch"] = "The widest reach there is and the slowest to arrive. Expensive enough that a short campaign is money spent before anybody has noticed.",
            ["channel.billboards"] = "Billboards",
            ["channel.billboards.pitch"] = "Physical, local and impossible to skip. Slow, and what it buys stays bought for a while after the posters come down.",
            ["channel.creators"] = "Creators",
            ["channel.creators.pitch"] = "Somebody with an audience talks about you. A sharp spike, a short memory, and a real chance of the wrong person saying the wrong thing.",
            ["region.america"] = "America",
            ["region.america.note"] = "Where the accelerators ship first and where everyone else already is.",
            ["region.europe"] = "Europe",
            ["region.europe.note"] = "Cheaper to run, slower to supply, and a regulator that will read what you publish.",
            ["region.asia"] = "Asia",
            ["region.asia.note"] = "Closest to the factories. Silicon is cheap here and attention is not.",
            ["country.us"] = "United States",
            ["country.us.note"] = "First in line for every launch, and so is everybody else.",
            ["country.canada"] = "Canada",
            ["country.canada.note"] = "The research is here. The capital is one border away.",
            ["country.brazil"] = "Brazil",
            ["country.brazil.note"] = "Almost nobody is competing for these users yet.",
            ["country.mexico"] = "Mexico",
            ["country.mexico.note"] = "Cheap to staff, close enough to ship to.",
            ["country.uk"] = "United Kingdom",
            ["country.uk.note"] = "Deep research bench, thin domestic market.",
            ["country.germany"] = "Germany",
            ["country.germany.note"] = "Industrial customers who pay on time and read the contract.",
            ["country.france"] = "France",
            ["country.france.note"] = "State money is available if the state likes you.",
            ["country.poland"] = "Poland",
            ["country.poland.note"] = "Low tax, low payroll, hardware arrives late.",
            ["country.ireland"] = "Ireland",
            ["country.ireland.note"] = "The tax rate is the entire pitch.",
            ["country.switzerland"] = "Switzerland",
            ["country.switzerland.note"] = "Expensive people, cheap taxes, quiet neighbours.",
            ["country.japan"] = "Japan",
            ["country.japan.note"] = "Patient customers, punishing tax.",
            ["country.southkorea"] = "South Korea",
            ["country.southkorea.note"] = "Memory is made here, so memory is cheap here.",
            ["country.taiwan"] = "Taiwan",
            ["country.taiwan.note"] = "The wafers start here. Nothing is closer to the source.",
            ["country.singapore"] = "Singapore",
            ["country.singapore.note"] = "A small market that everything in the region routes through.",
            ["country.india"] = "India",
            ["country.india.note"] = "More engineers than anywhere, less silicon than anywhere.",
            ["country.china"] = "China",
            ["country.china.note"] = "Enormous demand, and export controls on everything you need.",
            ["job.mlengineer"] = "ML Engineer",
            ["job.mlengineer.blurb"] = "Writes the training code and the evaluation harness. The people who make the plan actually run.",
            ["job.scientist"] = "Research Scientist",
            ["job.scientist.blurb"] = "Decides what is worth training before anybody trains it. Expensive, and the reason a lab is a lab.",
            ["job.software"] = "Software Engineer",
            ["job.software.blurb"] = "The product around the model: the API, the app, the thing customers touch.",
            ["job.data"] = "Data Engineer",
            ["job.data.blurb"] = "Corpora, cleaning, deduplication. Quiet work that decides what the model is made of.",
            ["job.safety"] = "Safety Engineer",
            ["job.safety.blurb"] = "Red teams the model before a regulator does. Cheap next to one inspection.",
            ["job.operations"] = "Operations Lead",
            ["job.operations.blurb"] = "Runs the floor, the spend and the launches. Nobody notices them until they leave.",
            ["job.coordinator"] = "Team Coordinator",
            ["job.coordinator.blurb"] = "Keeps seven disciplines pointed the same way. Raises the ceiling on everybody else.",
            ["piece.plant"] = "Rubber Plant",
            ["piece.plant.blurb"] = "Costs almost nothing and makes the corner look like somebody works here.",
            ["piece.whiteboard"] = "Whiteboard Wall",
            ["piece.whiteboard.blurb"] = "Somewhere to argue about an architecture without opening a document.",
            ["piece.desk"] = "Desk And Chair",
            ["piece.desk.blurb"] = "One more seat. Desks are what caps hiring, so this is the one that grows the lab.",
            ["piece.bookshelf"] = "Reference Shelf",
            ["piece.bookshelf.blurb"] = "Papers nobody reads, in a room where everybody says they have.",
            ["piece.sofa"] = "Break Sofa",
            ["piece.sofa.blurb"] = "Twenty minutes off the desk. The people who take it stay longer.",
            ["piece.standingdesk"] = "Standing Rig",
            ["piece.standingdesk.blurb"] = "A seat and a better one. Costs more than a desk and is worth it to whoever gets it.",
            ["piece.coffeebar"] = "Espresso Bar",
            ["piece.coffeebar.blurb"] = "The most reliable productivity intervention in the building.",
            ["piece.art"] = "Commissioned Piece",
            ["piece.art.blurb"] = "Expensive, does nothing, and everybody who visits mentions it.",
            ["piece.aquarium"] = "Reef Tank",
            ["piece.aquarium.blurb"] = "Six hundred litres of maintenance that the whole floor stands and watches.",
            ["piece.sleeppod"] = "Sleep Pod",
            ["piece.sleeppod.blurb"] = "For the nights before a launch. Nobody admits to needing one until they use it.",
            ["rack.openframe.pitch"] = "Four posts and some cable ties. The room is the cooling, which works until the room is full.",
            ["rack.openframe.note"] = "Cheapest per slot in the game and the first thing to throttle. Fine while the hall is half empty and a false economy once it is not.",
            ["rack.enclosed.pitch"] = "Doors, a blanking kit and a proper airflow path. What a normal room is full of.",
            ["rack.enclosed.note"] = "The one to beat. Neither the cheap answer nor the dense one.",
            ["rack.highdensity.pitch"] = "Rear door heat exchanger. Twice the accelerators in the same footprint, and it still sheds what they make.",
            ["rack.highdensity.note"] = "Dear per slot and it buys floor space, which is the thing a hall runs out of before it runs out of money.",
            ["rack.immersion.pitch"] = "The whole thing sits in dielectric fluid. Nothing else in the game fits this much in one square, and nothing else costs this much to keep.",
            ["rack.immersion.note"] = "Worth it when the floor is the binding constraint and a waste of nine thousand a month when it is not.",
            ["modeltype.general"] = "General purpose",
