            // ---- the funding screen and the five facilities ------------------------------------------
            ["funding.title"] = "BANK I DOTACJE",
            ["funding.borrowing"] = "KREDYTY",
            ["funding.strap"] = "Założyciele mają {0} po rundach: {1}. Zebrane łącznie: {2}. Nastroje inwestorów: {3}.",
            ["loan.commercial"] = "KOMERCYJNY",
            ["loan.state"] = "PROGRAM PAŃSTWOWY",
            ["loan.monthly_instalment"] = "RATA MIESIĘCZNA",
            ["loan.monthly_commission"] = "PROWIZJA MIESIĘCZNA",
            ["loan.back_in_total"] = "ZWROT ŁĄCZNIE",
            ["loan.open_facilities"] = "OTWARTE KREDYTY",
            ["loan.terms"] = "okres {0}, {1} do pierwszej raty",
            ["loan.left_of"] = "zostało {0} z {1}",
            ["loan.nothing_drawn"] = "Nic nie wzięte. Kredyt to gotówka teraz w zamian za stałą kwotę w stałym terminie, niezależnie od tego, jaki był kwartał.",
            ["loan.bridge.name"] = "Kredyt pomostowy",
            ["loan.bridge.desc"] = "Pół roku oddechu od kredytodawcy, który liczy, że zaraz zamkniesz rundę. Mały, szybki i wyceniony tak, jakby ta runda mogła nie dojść.",
            ["loan.equipment.name"] = "Kredyt na sprzęt",
            ["loan.equipment.desc"] = "Pod zastaw akceleratorów, nie firmy. Kredytodawcy jest wszystko jedno, co robią modele, liczy się, ile warty jest sprzęt, więc jest tanio i niewiele. Spóźnisz się z ratą i zabiorą flotę.",
            ["loan.venture.name"] = "Dług venture",
            ["loan.venture.desc"] = "Kapitał na wzrost, który nie rusza udziałów. Kredytodawca chce widzieć przychód, a gdy harmonogram ruszy, nie zatrzyma się na słaby kwartał.",
            ["loan.bond.name"] = "Obligacja korporacyjna",
            ["loan.bond.desc"] = "Prawdziwa emisja pod prawdziwy bilans. Tanie pieniądze jak na tę branżę, a przy tej skali spóźniona rata jest wydarzeniem publicznym.",
            ["loan.sovseed.name"] = "Państwowy grant obliczeniowy",
            ["loan.sovseed.desc"] = "Ministerstwo z pozycją w budżecie i czymś do udowodnienia. Miliard, na warunkach, których nikt nie nazwie hojnymi, pod warunkiem że zdolności zostają w kraju. Mniejszy niż pełny program i łatwiej po niego sięgnąć, a każdy dolar kosztuje więcej.",
            ["loan.sovereign.name"] = "Państwowy program mocy obliczeniowej",
            ["loan.sovereign.desc"] = "Państwo uznaje, że krajowe zdolności na froncie to infrastruktura, i wypisuje czek, żeby to udowodnić. Dziesięć miliardów teraz, prawie trzy razy tyle z powrotem przez jedenaście lat i rząd, który nie renegocjuje. Nic innego w tej grze nie rusza tylu pieniędzy i nic innego nie upada tak głośno.",

            // ---- making the architecture screen legible ----------------------------------------------
            ["arch.strap"] = "Zanim zaczniesz budować modele, możesz zbudować to, z czego modele się robi. Jeden program, raz, i każdy model, który potem wydasz, to dziedziczy: tańszy w utrzymaniu, lepszy jak na swój rozmiar, szybszy w treningu albo wszystko naraz. Trwa rok, a wynik to przedział, nie liczba.",
            ["arch.setting_and_share"] = "{0}   ·   {1} wysiłku",
            ["arch.cheaper_to_run"] = "o {0} tańszy w utrzymaniu niż to, co masz teraz",
            ["arch.more_from_each"] = "o {0} więcej zdolności z tych samych parametrów",
            ["arch.faster_runs"] = "o {0} szybszy trening, przy każdym uruchomieniu",
            ["arch.cheaper_tokens"] = "o {0} taniej za token, gdy modele już działają",
            ["arch.points_better"] = "{0} zdolności na wierzchu, jeszcze przed skalą",
            ["arch.no_better"] = "nie lepiej niż to, na czym już jeździsz",
            ["arch.shape.none"] = "Rodzina wycelowana w nic konkretnego. Równe rozłożenie wysiłku to decyzja i zwykle daje coś nie lepszego od opublikowanych technik, których i tak używasz.",
            ["arch.shape.sparsity"] = "Rodzina zbudowana pod tani rozruch. Ogromne modele, które budzą tylko część siebie na każdy token, więc serwujesz rozmiar, na który nikogo innego nie stać.",
            ["arch.shape.throughput"] = "Rodzina zbudowana pod tempo dostarczania. Te same treningi kończą się szybciej, więc wydajesz więcej modeli rocznie i zdążasz na okno premiery.",
            ["arch.shape.quality"] = "Rodzina zbudowana pod jakość. Każdy model, jaki z niej wyjdzie, punktuje wyżej przy tej samej mocy. To kumuluje się przez dekadę i najpóźniej widać to w księgach.",
            ["arch.shape.serving"] = "Rodzina zbudowana pod marżę. Nic, co widzi klient, a decyduje o tym, czy pójdziesz za kolejną obniżką ceny, którą ktoś zacznie.",
            ["arch.shape.reasoning"] = "Rodzina zbudowana pod myślenie. Zdolności, które nie biorą się z rozmiaru, czyli jedyna dźwignia, gdy wszyscy mają klastry tej samej wielkości.",

            // ---- what every research node actually is ------------------------------------------------
            ["node.finetuning.desc"] = "Weź cudzy model bazowy i naucz go robić jedną rzecz dobrze. Każda firma tu zaczyna i żadna nie zostaje.",
            ["node.humanfeedback.desc"] = "Naucz model, jak wygląda dobra odpowiedź, zamiast liczyć na szczęście. Zmniejsza ryzyko publicznej wtopy i otwiera dane o ludzkich preferencjach.",
            ["node.curatedcorpora.desc"] = "Deduplikacja, filtrowanie i dział prawny. Zamienia stertę zescrapowanego tekstu w coś, na czym warto trenować.",
            ["node.efficientattention.desc"] = "Kernele uwagi świadome pamięci i grupowane zapytania. Ten sam model, wyraźnie szybszy w treningu i tańszy w serwowaniu.",
            ["node.series.desc"] = "Wydaj kolejny model jako wersję poprzedniego, a nie jako obcego. Nazwa przenosi ze sobą publiczność, a przy słabym wydaniu przenosi też reputację.",
            ["node.coding.desc"] = "Kontekst wielkości repozytorium, uruchamianie testów i diffy jako sygnał treningowy. W 2022 prawie nikt tego nie chce. Do 2025 to segment, który płaci.",
            ["node.conversational.desc"] = "Ton, zachowanie przy odmowach i pamięć w obrębie sesji. Zamienia narzędzie, które ludzie testują, w produkt, który otwierają co rano.",
            ["node.automation.desc"] = "Ustrukturyzowane wyjście, długie dokumenty i wywołania narzędzi, które przejdą przez dział zgodności. Sprzedaje się wolno, a potem już nie odchodzi.",
            ["node.agentic.desc"] = "Model z własną maszyną: powłoka, system plików i godziny pracy bez nadzoru. Najdroższa pozycja w drzewie i jedyna, która rządzi końcówką gry.",
            ["node.multimodal.desc"] = "Obraz i dźwięk na wejściu, obraz i dźwięk na wyjściu. Drogie, a od 2025 kupujący przestają to traktować jak funkcję i zaczynają jak minimum.",
            ["node.scalinglaws.desc"] = "Policz dokładnie, jak strata spada z parametrami i tokenami, i przestań zgadywać, co wyjdzie z treningu. Otwiera sprzęt na własność zamiast wynajmu.",
            ["node.mixtureofexperts.desc"] = "Kieruj każdy token do ułamka sieci. Ćwierć mocy na token i dział badawczy, który musi być na tyle dobry, żeby to utrzymać w ryzach.",
            ["node.lowprecision.desc"] = "Trzymaj liczby na ośmiu bitach i pilnuj, żeby trening się nie rozsypał. Prawie dwa razy więcej mocy z tego samego klastra i krzywa straty, która potrafi się rozjechać na ostatniej prostej, bez niczego w zamian za pieniądze.",
            ["node.singleprecision.desc"] = "Przestań wozić sześćdziesiąt cztery bity mantysy, których nikt nie używa. Jedna trzecia przepustowości więcej z klastra, który już wynajmujesz, za dwa tygodnie czyjejś pracy.",
            ["node.mixedprecision.desc"] = "Trzymaj wagi główne szeroko, a arytmetykę wąsko. Połowa pamięci i prawie dwa razy większa przepustowość, bez ryzyka, jakie niosą osiem bitów.",
            ["node.dedup.desc"] = "Znajdź duplikaty przybliżone, nie tylko dokładne. Crawl jest pełen tej samej strony pod czterdziestoma domenami, a trening, który czyta ją czterdzieści razy, uczy się raz i płaci czterdzieści.",
            ["node.pipeline_data.desc"] = "Wciągaj, czyść i licencjonuj tekst na bieżąco, a nie raz do roku w paczce. Kupujesz tym model, który wie, co było w tym miesiącu.",
            ["node.context.desc"] = "Utrzymaj naraz całe repozytorium albo rok dokumentów. To sprawia, że korporacje zostają, zamiast się rozglądać.",
            ["node.licensed.desc"] = "Książki, czasopisma i wszystko inne, co ma właściciela. Negocjacje trwają, a różnica w jakości nie jest subtelna.",
            ["node.autonomousagents.desc"] = "Model przestaje odpowiadać i zaczyna działać: wywołuje narzędzia, kręci pętle, kończy zadania, których nikt nie pilnował. Cały rynek agentów przechodzi przez ten węzeł.",
            ["node.syntheticdata.desc"] = "Otwarta sieć się kończy. Od tego momentu model uczy się z tekstu napisanego przez model, co działa dużo lepiej, niż brzmi, i tylko dopóki twój model jest wystarczająco dobry, żeby go napisać.",
            ["node.reasoning.desc"] = "Naucz model wydawać czas inferencji na myślenie. Rozwiązuje problemy, których nic innego nie ruszy, a rachunek za serwowanie rośnie dwuipółkrotnie.",
            ["node.longcontext.desc"] = "Rzadkość i bardzo długie okno w jednym modelu, bez psucia jednego przez drugie.",
            ["node.datacenter.desc"] = "Umowy na prąd, grunt, stacje transformatorowe i harmonogram budowy liczony w latach. Po drugiej stronie leży najtańszy FLOP w tej grze.",
            ["node.assa1.desc"] = "Automatyczny samoaudyt bezpieczeństwa już działa. To licencja na zestaw zewnętrznych algorytmów, które się do niego dokłada, a kupujesz nią to, że automatyczne przebiegi przestają za każdym razem przeoczać tę samą klasę dziur.",
            ["node.assa2.desc"] = "Każdy audyt, jaki firma kiedykolwiek zrobiła, jest teraz danymi treningowymi. Wystarczy ich, żeby postawić system atakujący wielkości samego modelu, zamknięty razem z nim.",
            ["node.assa3.desc"] = "Stała populacja audytorów zamiast przebiegu, który się uruchamia i kończy. Każdy wyspecjalizowany, każdy karmiony tym, co znalazły pozostałe, działający przeciw każdemu modelowi, jaki firma wydała.",
            ["node.red1.desc"] = "Katalog ręcznie pisanych ataków staje się maszyną: sam generuje próby, zachowuje te, które podeszły najbliżej, i je mutuje.",
            ["node.red2.desc"] = "Długie kampanie z celem, budżetem i zapisem, wymierzone w jedną klasę awarii naraz. Każda nieudana próba jest zachowana, bo nieudany atak to najbardziej użyteczna rzecz, jaką ktokolwiek ma o następnym.",
            ["node.red3.desc"] = "Stały zespół agentów, który nigdy nie przestaje i nic nie wydaje. Atakują każdy model w sprzedaży, bez przerwy, i po każdej porażce są lepsi.",
            ["node.data0.desc"] = "Dane użytkowników są wyjęte ze zwykłej ścieżki pracy modelu i trzymane tam, gdzie musi poprosić o dostęp. To różnica między wyciekiem logu a wyciekiem listy klientów.",
            ["node.data1.desc"] = "Wszystko wrażliwe leży zaszyfrowane, w magazynie z własną krótką listą dostępu. Nie powstrzyma włamania. Sprawia, że to, co wypłynie, jest nie do odczytania.",
            ["node.data2.desc"] = "Dane treningowe są przetwarzane tak, że z tego, czego model się nauczył, nie da się odtworzyć pojedynczej osoby. Pierwszy poziom, który regulator przyjmuje jako argument, a nie jako obietnicę.",
            ["node.data3.desc"] = "Prywatność przestaje być czymś dokładanym po treningu i staje się częścią tego, jak trening działa. Połowa rzeczy, które mogłyby skończyć firmę, już jej nie skończy.",
            ["node.sharding.desc"] = "Adam trzyma dwa momenty i pełną kopię każdej wagi, czyli trzykrotność modelu na każdym akceleratorze, wszędzie identyczną. Rozprosz to po klastrze, a każda maszyna trzyma swój kawałek.",
            ["node.pipeline.desc"] = "Potnij model na etapy i daj każdej maszynie etap zamiast kopii. Warstwy nie muszą się już nigdzie mieścić, mieści się tylko etap.",
            ["node.ultrareadiness.desc"] = "Trening tej długości będzie tracić maszyny w trakcie. Rób checkpointy na tyle często, żeby to przeżyć, wznawiaj bez człowieka i utrzymaj tysiące akceleratorów w rytmie przez miesiące.",
            ["node.learnedrouting.desc"] = "Rzadki model jest tak dobry, jak to, co decyduje, którzy eksperci zobaczą token. Wytrenuj router zamiast hashować, wyrównaj obciążenie ekspertów i przestań pozwalać połowie sieci nigdy nie zostać wybraną.",
            ["node.expertparallelism.desc"] = "Postaw każdego eksperta na własnych maszynach i kieruj do nich tokeny przez sieć. Model nie musi się już nigdzie mieścić, a to, co kupujesz, to sieć.",
            ["node.fusedkernels.desc"] = "Przestań zapisywać wyniki pośrednie do pamięci między każdą operacją. Jeden kernel na cały blok karmi jednostki arytmetyczne zamiast zajmować magistralę pamięci.",
            ["node.overlappedcollectives.desc"] = "Klaster spędza sporą część każdego kroku, czekając aż gradienty skończą się przemieszczać. Zacznij następny blok obliczeń, kiedy one są jeszcze w drodze, a czekanie przestaje być czasem.",
            ["node.curriculumtraining.desc"] = "Kolejność, w jakiej przychodzą tokeny, zmienia to, co model z nich wyciąga. Ułóż korpus, zamiast go tasować, i podnoś trudność w tempie, jakie model wytrzyma.",
            ["node.selfdistillation.desc"] = "Trenuj kolejny model przeciw temu, który już masz, a nie tylko przeciw danym. Uczeń dochodzi do poziomu nauczyciela mniejszym kosztem, a potem go wyprzedza.",
            ["node.quantisedserving.desc"] = "Serwuj na ośmiu bitach zamiast szesnastu. Wagi są tymi samymi wagami, odpowiedzi są wystarczająco tymi samymi odpowiedziami, a maszyna mieści dwa razy więcej.",
            ["node.speculativedecoding.desc"] = "Mały model zgaduje kilka następnych tokenów, a duży sprawdza je wszystkie naraz. Większość trafień jest dobra, a odrzucenie tych złych nic nie kosztuje.",
            ["node.processsupervision.desc"] = "Nagradzaj rozwiązanie, nie odpowiedź. Model oceniany tylko po ostatniej linijce uczy się ją zgadywać, a oceniany na każdym kroku uczy się do niej dojść.",
            ["node.inferencetimesearch.desc"] = "Wydawaj moc wtedy, gdy padnie pytanie, a nie tylko przy budowie modelu. Losuj kilka prób, oceń je, zostaw najlepszą.",
            ["node.hybrid.desc"] = "Uwaga tam, gdzie zarabia na siebie, i rekurencja wszędzie indziej. Długi kontekst przestaje być drogi.",
            ["node.recursive.desc"] = "Modele zaczynają projektować kolejne modele i pętla się zamyka. Każdy trening po tym jest po części napisany przez poprzedni.",
            ["node.asi.desc"] = "Od tego momentu firma nie jest już najzdolniejszą rzeczą w budynku. Rządy będą chciały kontraktów. Te, które nie będą, będą chciały kar.",

            // ---- the remaining screens ---------------------------------------------------------------
            ["page.fleet"] = "MOC",
            ["page.fleet.strap"] = "{0} na tabliczce, {1} do użycia. {2} dziennie za utrzymanie, {3} dziennie traci na wartości.",
            ["page.business"] = "BIZNES",
            ["page.business.strap"] = "Stawka rynkowa to dziś {0} za miliard tokenów. To, ile bierzesz wobec niej, decyduje o twoim udziale, a to, ile rozdajesz, decyduje, ile z tego, co serwujesz, jest cokolwiek warte.",
            ["page.team"] = "ZESPÓŁ",
            ["page.team.strap"] = "{0} z {1} biurek w: {2}. Lista płac: {3} dziennie. Każda dziedzina się nasyca, więc siódma osoba w niej dokłada ułamek tego, co dołożyła druga.",
            ["page.team.remote"] = "Do tego zdalnie: {0}.",
            ["page.marketing"] = "MARKETING",
            ["page.marketing.strap"] = "Reklama kupuje uwagę, nigdy jakość. Produkt, o którym nikt nie słyszał, przegrywa z tym, o którym słyszeli, a zły produkt, o którym słyszeli, zostaje wypróbowany i porzucony.",
            ["page.release"] = "WYDANIE",
            ["page.release.strap"] = "Skończone treningi czekają tutaj. Czekanie nie kosztuje wprost, a codziennie kosztuje pozycję: poprzeczka rynku rośnie niezależnie od tego, czy wydajesz.",
            ["upgrade.empty.title"] = "NIE MA CZEGO ULEPSZAĆ",
            ["upgrade.empty.body"] = "Tu serwisujesz model, który jest już w sprzedaży, bez ponownego treningu. Nic nie jest w sprzedaży, więc nie ma nad czym pracować. Najpierw zbuduj model, potem wróć i trzymaj go na czasie latami.",
            ["upgrade.empty.go"] = "ZAPROJEKTUJ MODEL",
            ["release.empty.title"] = "NIC NIE CZEKA",
            ["release.empty.body"] = "Tu leżą gotowe modele, zanim wystawisz je na sprzedaż. Najpierw musi skończyć się trening, żeby było o czym decydować, a rynek jest trudniejszy z każdym dniem, który zajmiesz.",
            ["release.empty.go"] = "ZAPROJEKTUJ MODEL",
            ["page.ranking"] = "RANKING",
            ["page.ranking.strap"] = "Zdolności, udział w rynku i marka, z wagami.",
            ["rank.price_and_share"] = "{0}   udział {1}",
            ["rank.share"] = "udział {0}",
