            ["rent.meter.capacity_note"] = "obecnie {0}",
            ["rent.meter.bill"] = "NA DZIEŃ",
            ["rent.meter.bill_note"] = "{0} za PF-dzień",
            ["rent.meter.delivered"] = "DOSTARCZANE",
            ["rent.meter.delivered_note"] = "{0} tego, za co płacisz",
            ["rent.band.caption"] = "TYLE MOCY UTRZYMA MNIEJ WIĘCEJ",
            ["rent.band.nobody"] = "zwykłych kont. Nikt się jeszcze nie zapisał, więc wszystko stoi bezczynnie i za wszystko płacisz.",
            ["rent.band.room"] = "zwykłych kont, a masz {0}. Jest zapas.",
