            // ---- the twenty six explanations the rest of the game was missing ------------------------
            ["tech.revenue.title"] = "PRZYCHÓD",
            ["tech.revenue.what"] = "Wszystko, co klienci zapłacili w tym miesiącu, zanim odejmiesz choć jeden swój rachunek. Liczba z pierwszej linijki rachunku każdej firmy.",
            ["tech.revenue.affects"] = "Sam z siebie nic. Finansuje badania, sprzęt i pensje, a firma może go zwiększać co miesiąc i i tak bankrutować.",
            ["tech.revenue.high"] = "Ludzie używają tego, co zbudowałeś, i płacą. To też moment, w którym rośnie rachunek za serwowanie, bo każdy sprzedany token musisz policzyć.",
            ["tech.revenue.low"] = "Albo nikt o tobie nie słyszał, albo słyszał i wybrał kogoś innego. Tutaj wygląda to identycznie, a na ekranie marketingu zupełnie inaczej.",
            ["tech.margin.title"] = "MARŻA",
            ["tech.margin.what"] = "Ile zostaje z każdego złotego po opłaceniu odpowiedzi na pytanie. Sklep sprzedający po kosztach ma obrót i nie ma marży, a z obrotu nikt nie żyje.",
            ["tech.margin.affects"] = "Czy warto rosnąć. Przy ujemnej marży każdy nowy klient kosztuje cię pieniądze, więc udana premiera jest tym, co dobija firmę.",
            ["tech.margin.high"] = "Możesz pójść za kolejną obniżką ceny, którą ktoś zacznie. Marża kupuje prawo do udziału w wojnie cenowej.",
            ["tech.margin.low"] = "Jesteś o jedną cudzą obniżkę od sprzedaży ze stratą i dowiesz się o tym w dniu jej ogłoszenia.",
            ["tech.tokenprice.title"] = "CENA ZA MILION TOKENÓW",
            ["tech.tokenprice.what"] = "Token to mniej więcej trzy czwarte słowa. To, ile bierzesz za milion, czyli za jakieś siedemset tysięcy słów, czyli dziewięć grubych powieści.",
            ["tech.tokenprice.affects"] = "Przychód z użytkownika i to, ilu zostanie. Cała branża tnie tę cenę mniej więcej o połowę rocznie, niezależnie od ciebie, więc stanie w miejscu to podwyżka.",
            ["tech.tokenprice.high"] = "Więcej pieniędzy od każdego, kto zostanie. Korporacjom przeszkadza to najmniej, konsumenci odchodzą pierwsi i najszybciej.",
            ["tech.tokenprice.low"] = "Zdobywasz tych, którzy wybierali po cenie, i obsługujesz każdego z marży, którą właśnie obciąłeś. Tanio działa tylko wtedy, gdy model jest tani w utrzymaniu.",
            ["tech.burn.title"] = "ILE KOSZTUJE DZIEŃ",
            ["tech.burn.what"] = "Wszystko, co firma wydaje od północy do północy, niezależnie od tego, czy ktokolwiek coś kupi. Pensje, czynsz, moc obliczeniowa, odsetki.",
            ["tech.burn.affects"] = "Jak długo starczy pieniędzy. Gotówka podzielona przez to, to liczba dni, jakie ci zostały, żeby mieć w czymś rację.",
            ["tech.burn.high"] = "Duża firma, która szybko się porusza. To też firma, która nie przeżyje jednego cichego kwartału, bo żaden z tych rachunków nie zatrzymuje się razem z przychodem.",
            ["tech.burn.low"] = "Możesz czekać, a czekanie to w tej grze prawdziwa strategia. To też mały zespół trenujący małe modele, podczas gdy ktoś inny trenuje duży.",
            ["tech.valuation.title"] = "WYCENA FIRMY",
            ["tech.valuation.what"] = "Ile ktoś zapłaciłby dziś za całą firmę. Nikt nie składa oferty, a i tak to ta liczba decyduje, ile siebie oddajesz za pieniądze.",
            ["tech.valuation.affects"] = "Ile kosztuje runda finansowania. Zebranie dziesięciu milionów przy wycenie stu milionów kosztuje cię jedną dziesiątą firmy, przy miliardzie jedną setną.",
            ["tech.valuation.high"] = "Pieniądze są teraz dla ciebie tanie. To moment na rundę i dokładnie wtedy czujesz, że nie musisz.",
            ["tech.valuation.low"] = "Każda złotówka z rundy kosztuje cię więcej firmy. Kredyt zaczyna wyglądać lepiej i tak firmy kończą, będąc winne więcej, niż są warte.",
            ["tech.equity.title"] = "UDZIAŁ ZAŁOŻYCIELA",
            ["tech.equity.what"] = "Ile firmy jest jeszcze twoje. Startuje z całością i tylko spada, bo sprzedanego udziału nie kupisz z powrotem.",
            ["tech.equity.affects"] = "Nic w symulacji i wszystko w tym, co znaczy wygrać. Firma, której masz jedną dziesiątą, a pobiła wszystkich, była czyjąś cudzą wygraną.",
            ["tech.equity.high"] = "Zostało twoje. Zwykle dlatego, że wzrost finansowałeś z przychodu, co jest wolniejsze i jest trudniejszym sposobem grania.",
            ["tech.equity.low"] = "Kupiłeś tempo za własność. Uczciwy handel i moment, w którym ci, co kupili resztę, zaczynają mieć zdanie.",
            ["tech.instalment.title"] = "RATA I PROWIZJA",
            ["tech.instalment.what"] = "Dwa różne rachunki pod jednym słowem. Rata spłaca kredyt i kończy się razem z nim. Prowizja to czynsz za samo posiadanie kredytu, nie spłaca nic i leci nawet w czasie karencji.",
            ["tech.instalment.affects"] = "Dzienny koszt, od dnia wypłaty kredytu do dnia spłaty. Oba są pobierane niezależnie od tego, jaki był kwartał.",
            ["tech.instalment.high"] = "Pożyczyłeś dużo, więc możesz zrobić teraz coś dużego. Rachunek przychodzi co miesiąc przez lata i nie interesuje go, co zrobiłeś z pieniędzmi.",
            ["tech.instalment.low"] = "Prawie nic nie wisisz, czyli wolność, i to też znaczy, że budujesz w tempie, na jakie pozwala twój własny przychód.",
            ["tech.petaflop.title"] = "PETAFLOP-DZIEŃ",
            ["tech.petaflop.what"] = "Jednostka, w której mierzy się trening, tak jak budowlaniec mierzy w roboczodniówkach. Jeden petaflop-dzień to maszyna licząca tysiąc bilionów działań na sekundę, przez dobę.",
            ["tech.petaflop.affects"] = "Ile trwa trening i ile kosztuje. Model potrzebuje ich ustalonej liczby, więc dwa razy większa flota to o połowę krótsze czekanie i ten sam rachunek.",
            ["tech.petaflop.high"] = "Treningi kończą się, póki pomysł jest jeszcze coś wart. Moc, której nie używasz, to moc, za którą i tak płacisz.",
            ["tech.petaflop.low"] = "Tanio i każdy trening trwa miesiącami. Front nie czeka, a model spóźniony o rok trafia na konkurencję z przyszłego roku.",
            ["tech.rentbuy.title"] = "WYNAJEM CZY WŁASNOŚĆ",
            ["tech.rentbuy.what"] = "Ten sam wybór co z autem do firmy: wynająć na dzień i płacić więcej za kilometr, albo kupić i wozić je ze sobą, czy jeździsz, czy nie.",
            ["tech.rentbuy.affects"] = "Koszt za petaflop i to, jak szybko możesz zmienić zdanie. Własny sprzęt to jakieś trzy razy taniej za jednostkę pracy i traci mniej więcej ćwierć wartości z każdą nową generacją.",
            ["tech.rentbuy.high"] = "Własność to najtańsza praca w tej grze i zakład o to, że za trzy lata nadal będziesz chciał tyle mocy.",
            ["tech.rentbuy.low"] = "Wynajem kosztuje więcej za jednostkę i możesz przestać jutro. W roku, w którym następna generacja jest trzy razy szybsza, ta swoboda była warta każdej złotówki.",
            ["tech.reserved.title"] = "MOC ZAREZERWOWANA",
            ["tech.reserved.what"] = "Różnica między stolikiem zarezerwowanym a przyjściem na chybił trafił. Zarezerwowana moc jest twoja, choćby wszyscy jej chcieli, a wspólna pula kolejkuje, gdy chcą jej wszyscy.",
            ["tech.reserved.affects"] = "Jak szybko klienci dostają odpowiedzi, gdy flota jest zajęta. Powyżej osiemdziesięciu procent obciążenia zapytanie trwa kilka razy dłużej, a ludzie odchodzą od tego szybciej niż od ceny.",
            ["tech.reserved.high"] = "Twoja usługa zostaje szybka w dniu, w którym wszyscy przychodzą naraz, czyli zwykle dzień po dobrej premierze.",
            ["tech.reserved.low"] = "Płacisz mniej za petaflop, a użytkownicy poznają smak kolejki dokładnie wtedy, gdy masz ich najwięcej.",
            ["tech.split.title"] = "PODZIAŁ KLASTRA",
            ["tech.split.what"] = "Jeden klaster, dwa zadania. Te same akceleratory, które trenują model, odpowiadają twoim użytkownikom, a firma robi obie rzeczy tylko wtedy, gdy zdecyduje, ile której dać.",
            ["tech.split.affects"] = "Jak szybko kończy się każda długa robota i ile tokenów zdołasz zaserwować w jej trakcie. Nic nie jest rezerwowane, gdy nic się nie buduje: w spokojnym tygodniu klienci mają całą flotę.",
            ["tech.split.high"] = "Treningi i badania kończą się miesiące wcześniej, a tylko tak da się być pierwszym. Usługa zwalnia dokładnie na ten czas, a ludzie odchodzą od wolnego produktu.",
            ["tech.split.low"] = "Użytkownicy dostają szybką usługę, a ty zatrzymujesz przychód, który za nią idzie, ale każdy rozpoczęty program ląduje odpowiednio później.",
            ["tech.headcount.title"] = "STANOWISKA",
            ["tech.headcount.what"] = "Ile osób może tu fizycznie pracować. Biurko to miejsce w twoim biurze i nie zatrudnisz jedenastej osoby w pokoju z dziesięcioma biurkami.",
            ["tech.headcount.affects"] = "Tempo badań i rachunek za pensje każdego dnia. Limit stawia biuro, więc powiększenie zespołu zaczyna się od przeprowadzki, a nie od rekrutacji.",
            ["tech.headcount.high"] = "Badania idą szybciej i każdy z nich dostaje pensję również w cichym miesiącu. Dziesięć osób to nie dziesięć razy jedna, zysk się spłaszcza w miarę zapełniania pokoju.",
            ["tech.headcount.low"] = "Tanio, zwinnie i wszystko trwa dłużej. Założyciel sam w garażu to prawdziwy sposób grania i ma sufit.",
            ["tech.wage.title"] = "STAWKA GODZINOWA",
            ["tech.wage.what"] = "Ile oferujesz. Każdy kandydat ma w głowie prywatną liczbę, poniżej której nie zejdzie, a ty nigdy jej nie zobaczysz.",
            ["tech.wage.affects"] = "Czy się zgodzą i dzienny koszt na zawsze potem. Pensja to nie zakup, to abonament wykupiony na człowieka.",
            ["tech.wage.high"] = "Zgadzają się od razu i właśnie ustaliłeś cenę wszystkich, których zatrudnisz po nich.",
            ["tech.wage.low"] = "Odmawiają, albo się zgadzają i po cichu kupiłeś kogoś, kto był wart mniej, niż liczyłeś.",
            ["tech.talent.title"] = "ILE WART JEST ZESPÓŁ",
            ["tech.talent.what"] = "Nie ilu ludzi, tylko jak dobrych. Dwóch świetnych badaczy i ośmiu porządnych to inna firma niż dziesięciu porządnych za tę samą pensję.",
            ["tech.talent.affects"] = "Punkty badawcze dziennie i to, jak daleko gotowy model wyląduje od tego, co obiecał ekran tworzenia.",
            ["tech.talent.high"] = "Treningi lądują blisko prognozy, a drzewo się rusza. To też najdroższa lista płac w tej grze.",
            ["tech.talent.low"] = "Stać cię, a twoje prognozy stają się optymizmem zamiast planem. Dowiadujesz się tego cztery miesiące po starcie treningu.",
            ["tech.awareness.title"] = "KTO O TOBIE SŁYSZAŁ",
            ["tech.awareness.what"] = "Jaka część każdej publiczności wie, że twoja firma istnieje. Piekarnia w bocznej uliczce z najlepszym chlebem w mieście i tak sprzedaje mniej niż ta na rynku.",
            ["tech.awareness.affects"] = "Czy twój produkt jest w ogóle brany pod uwagę. Nigdy nie rusza tego, jak dobry jest produkt, więc reklamowanie słabego kupuje ludzi, którzy spróbują raz i odejdą.",
            ["tech.awareness.high"] = "Każda premiera startuje z publicznością, która już czeka. Rozpoznawalność sama opada, więc to kran, który trzymasz odkręcony, a nie mur, który stawiasz.",
            ["tech.awareness.low"] = "Możesz wydać najlepszy model na rynku i patrzeć, jak gorszy sprzedaje się lepiej, bo nikt nie wybierze czegoś, o czym nie słyszał.",
            ["tech.channel.title"] = "KANAŁY",
            ["tech.channel.what"] = "Gdzie idzie reklama. Sześć i żaden nie jest najlepszy: każdy dociera do innej publiczności w innym tempie, a to, co robi z twoją reputacją, jest częścią ceny.",
            ["tech.channel.affects"] = "Rozpoznawalność w publicznościach, które ten kanał lubi, i twoja reputacja, w górę albo w dół. Social jest głośny, tani i jako jedyny może cię kosztować reputację.",
            ["tech.channel.high"] = "Trzy naraz nadrabiają swoje słabości. To limit, bo powyżej trzech kombinacja przestaje cokolwiek znaczyć.",
            ["tech.channel.low"] = "Jeden kanał jest tani i dociera do jednej publiczności. Zupełnie sensowne, gdy wiesz dokładnie, komu sprzedajesz.",
            ["tech.campaign.title"] = "DŁUGOŚĆ KAMPANII",
            ["tech.campaign.what"] = "Na jak długo się zobowiązujesz. Dłuższe umowy są tańsze dziennie, a bezterminowa kosztuje o ćwierć więcej, tak jak każdy karnet na siłownię.",
            ["tech.campaign.affects"] = "Koszt dzienny i to, co możesz przerwać. Rozpoznawalność blednie w tygodniach, więc kampania, która się kończy, to kampania, której efekt kończy się wkrótce potem.",
            ["tech.campaign.high"] = "Pół roku po najlepszej stawce, płatne niezależnie od tego, co stanie się z przychodem w czwartym miesiącu.",
            ["tech.campaign.low"] = "Płacisz dopłatę za możliwość wyjścia, co opłaca się dokładnie w tych miesiącach, w których miało ci być potrzebne.",
            ["tech.par.title"] = "POPRZECZKA RYNKU",
            ["tech.par.what"] = "Jak dobry musi być model, żeby uchodzić dziś za zwyczajny. To nie jest reguła, którą ktoś napisał, tylko średnia z tego, co wszyscy już wydali, i idzie tylko w górę.",
            ["tech.par.affects"] = "Z czym twój model jest porównywany w dniu wejścia do sprzedaży, a nie w dniu rozpoczęcia treningu.",
            ["tech.par.high"] = "Trudny rynek, a model, który go pobija, jest wart bardzo dużo, bo wszyscy to widzą.",
            ["tech.par.low"] = "Łatwy rynek, na chwilę. Poprzeczka rośnie niezależnie od tego, czy wydajesz, więc gotowy model leżący na półce z każdym dniem jest gorszy.",
            ["tech.shelf.title"] = "CZEKANIE Z WYDANIEM",
            ["tech.shelf.what"] = "Gotowy model, którego jeszcze nie wystawiłeś. Przechowanie nic nie kosztuje, a on przez cały czas po cichu traci na wartości.",
            ["tech.shelf.affects"] = "Bezpośrednio nic, a twoją pozycję codziennie, bo poprzeczka rynku rośnie, kiedy się zastanawiasz.",
            ["tech.shelf.high"] = "Czekanie bywa słuszne: okno premiery, cudza zapowiedź do ominięcia, cena do ustalenia.",
            ["tech.shelf.low"] = "Wydanie w dniu ukończenia jest zwykle słuszne i to jest opcja, z której ludzie sami się wygadują.",
            ["tech.capability.title"] = "ZDOLNOŚCI",
            ["tech.capability.what"] = "Jedna liczba mówiąca, jak dobry jest model, tak jak jedna ocena zastępuje cały test samochodu. Wszyscy w tej grze są mierzeni tą samą skalą, ty też.",
            ["tech.capability.affects"] = "Jak atrakcyjny jest twój produkt dla każdej publiczności, przed ceną i przed tym, czy ktoś o tobie słyszał.",
            ["tech.capability.high"] = "Jesteś na froncie. To też najdroższe miejsce do stania i samo stanie tam nie płaci pensji.",
            ["tech.capability.low"] = "Jesteś z tyłu, a z tyłu da się przeżyć: tani wystarczający model sprzedawany ludziom, którzy nigdy nie potrzebowali frontu, to prawdziwy biznes.",
            ["tech.share.title"] = "UDZIAŁ W RYNKU",
            ["tech.share.what"] = "Jaka część ludzi kupujących tego rodzaju rzeczy kupuje twoją. Nie ilu masz ludzi, tylko ilu z tych, którzy istnieją.",
            ["tech.share.affects"] = "Przychód, reputację i to, jak głośno wyląduje twoja następna premiera. Udział przesuwa się tygodniami, nigdy nie teleportuje się dlatego, że ktoś wydał we wtorek.",
            ["tech.share.high"] = "Ludzie zostają przy tym, czego już używają, więc przewaga broni się sama. To też mnóstwo tokenów do policzenia, codziennie, na zawsze.",
            ["tech.share.low"] = "Miejsce na wzrost, a powodem, dla którego nikt cię nie rozważa, jest zwykle rozpoznawalność, a nie jakość.",
            ["tech.points.title"] = "PUNKTY BADAWCZE",
            ["tech.points.what"] = "W czym mierzy się tutaj wiedzę. Za pieniądze nie kupisz całego drzewa: czterokrotność budżetu daje dwa razy tyle punktów, więc większość trzeba zarobić budowaniem.",
            ["tech.points.affects"] = "Które węzły możesz zacząć. Każdy węzeł kosztuje punkty i trochę gotówki, a bramką są punkty.",
            ["tech.points.high"] = "Drzewo otwiera się szybko. Zwykle znaczy to, że trenowałeś i wydawałeś, bo to za to się je dostaje.",
            ["tech.points.low"] = "Bogata firma, która nic nie buduje, niczego się nie uczy, i dowiaduje się o tym dwa lata później, gdy dobre węzły dalej są zamknięte.",
            ["tech.era.title"] = "ERY",
            ["tech.era.what"] = "Drzewo jest ułożone na kalendarzu, a nie jako lista zakupów. Era 1 to 2022, era 4 to rok 2026 i dalej, a wszystko widać od pierwszego dnia i to celowo.",
            ["tech.era.affects"] = "Kiedy węzeł można w ogóle zacząć. Masz widzieć nadchodzącą końcówkę gry i pod nią układać lata pomiędzy.",
            ["tech.era.high"] = "Późniejsze ery trzymają to, co rozstrzyga końcówkę, i nic tam nie jest osiągalne bez większości tego, co było wcześniej.",
            ["tech.era.low"] = "Wczesne węzły wyglądają na drobne i to one sprawiają, że wszystko po nich staje się na kieszeń.",
            ["tech.trait.title"] = "CECHY MODELU",
            ["tech.trait.what"] = "Rzeczy, które możesz poprawić w modelu już będącym w sprzedaży, bez ponownego treningu. Jak przegląd samochodu zamiast kupna nowego.",
            ["tech.trait.affects"] = "Pozycję modelu na rynku i koszt jego serwowania. Nie zrobi z małego modelu dużego, skala jest ustalana raz, przy treningu.",
            ["tech.trait.high"] = "Taniej i szybciej niż nowy trening, i trzyma produkt na czasie latami po dacie, w której powinien się zestarzeć.",
            ["tech.trait.low"] = "Wieczne ulepszanie nie pobije frontu. W pewnym momencie ktoś wytrenuje coś, do czego nie doserwisujesz się z dołu.",
            ["tech.traitlevel.title"] = "POZIOMY",
            ["tech.traitlevel.what"] = "Każdą cechę można poprawiać kilka razy, a każdy krok kosztuje więcej niż poprzedni i daje trochę mniej.",
            ["tech.traitlevel.affects"] = "Gotówkę, moc obliczeniową i kalendarz. Program ulepszeń trwa dniami i dzieli flotę z twoimi treningami.",
            ["tech.traitlevel.high"] = "Głęboko doinwestowany model bije nowszy zwykły, dokładnie do momentu, w którym przestaje.",
            ["tech.traitlevel.low"] = "Pierwszy poziom czegokolwiek to najtańsza poprawa w tej grze. Rozłożenie po jednym poziomie na kilka cech zwykle bije wpakowanie wszystkiego w jedną.",
            ["tech.pricing.title"] = "CENNIK",
            ["tech.pricing.what"] = "Ile bierzesz, w podziale na płatność za token i miesięczną subskrypcję. Większość klientów widzi tylko jedno z dwóch.",
            ["tech.pricing.affects"] = "Przychód z użytkownika, ilu zostanie i twoją reputację. Obniżka o połowę jest lubiana dokładnie tak samo, jak podwyżka o dwa razy jest źle widziana.",
            ["tech.pricing.high"] = "Więcej od każdego klienta, a cennik każdego konkurenta jest o jedno kliknięcie od twojego.",
            ["tech.pricing.low"] = "Zgarniasz tych, którzy wybierali po cenie. Najpierw upewnij się, że model jest tani w utrzymaniu, bo inaczej kupiłeś sobie klientów ze stratą.",
            ["tech.freetier.title"] = "PLAN DARMOWY",
            ["tech.freetier.what"] = "Ile ktoś dostaje bez płacenia. Darmowa próbka na straganie: kosztuje cię prawdziwe pieniądze i to dzięki niej większość ludzi w ogóle czegokolwiek próbuje.",
            ["tech.freetier.affects"] = "Reputację i to, ilu ludzi przychodzi, w zamian za rachunek za tokeny, których nikt nie opłacił.",
            ["tech.freetier.high"] = "Ludzie cię uwielbiają, a ty liczysz ogromną liczbę odpowiedzi za darmo.",
            ["tech.freetier.low"] = "Każdy token jest opłacony, a nieznajomy nie ma jak sprawdzić, czy twój model jest dobry, zanim zdecyduje.",

            // ---- the menu, the creator and the controls the rest of the game shares ------------------
            ["intro.money"] = "Dwanaście milionów dolarów, zero produktu i jedenaście miesięcy, zanim świat dowie się, po co to wszystko.",
            ["intro.month"] = "STYCZEŃ 2022",
            ["intro.curiosity"] = "Modele językowe to badawcza ciekawostka z publicznością może dziesięciu tysięcy osób.",
            ["intro.unpriced"] = "Nikt spoza branży nie wymieni ani jednego. Nic nie zostało zamienione w produkt. Nic nie ma ceny.",
            ["intro.rewritten"] = "Za jedenaście miesięcy okienko czatu dotrze do stu milionów ludzi, a każde założenie w tej branży zostanie przepisane dwa razy przed 2026.",
            ["intro.you_have"] = "Masz dwanaście milionów dolarów i żadnego produktu.",
            ["intro.timing"] = "Żadnej z decyzji przed tobą nie da się cofnąć. Większość z nich dotyczy wyczucia czasu.",
            ["intro.hook"] = "Konkurencja dopiero wyczuła potężny zysk. Zaczynaj, póki jeszcze jest czas.",
