            ["hud.speed_x1"] = "X1",
            ["hud.speed_x2"] = "X2",
            ["hud.speed_x3"] = "X3",
            ["hud.speed_x1_note"] = "Dzień po dniu, na tydzień, który coś znaczy. Wciśnij 1.",
            ["hud.speed_x2_note"] = "Tempo, pod które gra jest wyważona. Wciśnij 2.",
            ["hud.speed_x3_note"] = "Na miesiące między decyzjami. Wciśnij 3.",
            ["hud.skip_day_note"] = "Przepuszcza dokładnie jeden dzień i staje, i właśnie dlatego przydaje się na pauzie.",
            ["hud.company_info_note"] = "Kim jesteś, co masz i ile kosztował ten dzień, na wierzchu nad sceną.",
            ["insight.site"] = "Pomieszczenie i wszystko, co firma w nim ma. Stąd ogląda się dzień.",
            ["insight.model"] = "Co firma sprzedaje, ile na tym zarabia i dwie drogi zmiany: zbudować nowy albo ulepszyć ten, który już jest na rynku.",
            ["insight.research"] = "Kupujesz wiedzę, która otwiera całą resztę. Punkty biorą się z pracy, którą i tak wykonujesz, a same pieniądze nie nadążą.",
            ["insight.architecture"] = "Jaką rodzinę modelu budujesz. Rzadka mieszanka jest tania w serwowaniu jak na swój rozmiar i to jest cały powód, żeby ją mieć.",
            ["insight.upgrade"] = "Programy, które poprawiają model już będący w sprzedaży, bez trenowania go od nowa.",
            ["insight.team"] = "Zatrudniaj i patrz, ile kosztuje lista płac. Biurka ograniczają liczbę osób, więc tutaj zaczyna mieć znaczenie biuro.",
            ["insight.compute"] = "Wynajmij albo kup. Kupisz za wcześnie i masz aktywo, które traci na wartości; kupisz za późno, a klientów ma już ktoś inny.",
            ["insight.business"] = "Księgi. Przychód, spalanie gotówki, narastający podatek i ile firma naprawdę jest warta.",
            ["insight.release"] = "Wystaw gotowy model na sprzedaż, ustaw cenę albo zdejmij coś z rynku.",
            ["insight.capital"] = "Zbieraj pieniądze i obsługuj to, co jesteś winien. Dług jest tańszy od udziałów dokładnie do miesiąca, w którym nie masz czym zapłacić.",
            ["insight.ranking"] = "Każdy rywal na tej samej skali zdolności co ty, i to, co wydał.",
            ["insight.intel"] = "Kupione ostrzeżenie z wyprzedzeniem. Tania redakcja myli się co do jednej rzeczy na trzy i brzmi dokładnie tak pewnie jak droga.",
            ["insight.marketing"] = "Kampanie kupują uwagę i nigdy jakość. Słaby model mocno reklamowany zostanie wypróbowany i porzucony, co kosztuje cię dwa razy.",
            ["insight.news"] = "Serwis. Premiery, afery, regulatorzy i to, co mówi się o tobie.",
            ["insight.mail"] = "Listy, które czekają na odpowiedź: negocjacje płacowe, rachunek podatkowy i każda kara, na którą firma zapracowała.",
