            // ---- what the seven founder skills are ---------------------------------------------------
            ["skill.development.title"] = "PROGRAMOWANIE",
            ["skill.development.what"] = "Jak dobrze naprawdę budujesz. Nie pomysł, tylko wykonanie: różnica między planem modelu a modelem, który wyszedł tak, jak plan zapowiadał.",
            ["skill.development.affects"] = "Jak blisko gotowy trening ląduje od zdolności, którą zapowiedział kreator. Niskie programowanie znaczy, że obiecana liczba i otrzymana to dwie różne liczby.",
            ["skill.development.high"] = "Twoje prognozy stają się planem. Najbardziej opłaca się na starcie, gdy jeden trening to cała firma, a chybienie to cały rok.",
            ["skill.development.low"] = "Każdy trening to rzut monetą wokół liczby na ekranie. Da się przeżyć, jeśli trenujesz często, zabójcze, jeśli postawisz wszystko na jeden.",
            ["skill.management.title"] = "ZARZĄDZANIE",
            ["skill.management.what"] = "Czy firma marnuje pieniądze po drodze do tego, co robi. Każdy biznes ma swoją wersję tego i nikt tego nie zauważa aż do miesiąca, w którym to zaważy.",
            ["skill.management.affects"] = "Dzienny koszt, każdego dnia kampanii. To najmniejszy mnożnik z tej listy i jedyny, który leci piętnaście lat bez przerwy.",
            ["skill.management.high"] = "Ta sama firma kosztuje mniej. Nudne i kumuluje się w większy zapas czasu, niż daje jakakolwiek pojedyncza dobra decyzja.",
            ["skill.management.low"] = "Płacisz trochę więcej za wszystko, zawsze. Nic w tym dramatycznego i właśnie dlatego łatwo to zostawić na dnie.",
            ["skill.teamwork.title"] = "PRACA ZESPOŁOWA",
            ["skill.teamwork.what"] = "Ilu ludzi wsadzisz do jednego pokoju, zanim siódmy przestanie cokolwiek dokładać. Każda organizacja trafia na tę ścianę, a gdzie ona stoi, to właśnie ta umiejętność.",
            ["skill.teamwork.affects"] = "Jak późno zatrudnianie przestaje się opłacać. Przy niskiej, czwarta osoba w dziale to już w większości zmarnowana pensja.",
            ["skill.teamwork.high"] = "Możesz zbudować prawdziwą organizację, a nie założyciela z asystentami. Zaczyna się liczyć dopiero, gdy stać cię na dziesięć osób.",
            ["skill.teamwork.low"] = "Zostań mały i szybki. Zupełnie dobry sposób grania, który stawia sufit na końcówce gry.",
            ["skill.concept.title"] = "KONCEPCJA",
            ["skill.concept.what"] = "Wyczucie. Wiedza, który z pięciu kierunków jest wart roku, zanim ktokolwiek ma na to dowody.",
            ["skill.concept.affects"] = "Ile program architektoniczny wyciśnie z tego samego roku i tego samego budżetu. Jedyna umiejętność, która rusza poziom ponad modelem.",
            ["skill.concept.high"] = "Twoje rodziny wychodzą lepiej, niż powinien kupić włożony wysiłek. Ta różnica kumuluje się w każdym modelu, jaki potem wydasz.",
            ["skill.concept.low"] = "Dostajesz mniej więcej to, za co płacisz, co jest w porządku i jest też tym, jak grają wszyscy inni.",
            ["skill.software.title"] = "OPROGRAMOWANIE",
            ["skill.software.what"] = "Jak wydajnie to działa, kiedy już jest zbudowane. Ten sam model, na tych samych maszynach, odpowiada na te same pytania za mniej pieniędzy.",
            ["skill.software.affects"] = "Koszt każdego tokena, jaki kiedykolwiek zaserwujesz. Gdy masz już klientów, to rachunek, który przychodzi codziennie i rośnie razem z sukcesem.",
            ["skill.software.high"] = "Wzrost staje się tańszy, a nie droższy, i to jest różnica między skalowaniem a tonięciem.",
            ["skill.software.low"] = "Każdy nowy klient kosztuje cię więcej niż poprzedni. Nieważne, póki jesteś mały, i to powód, dla którego niektóre laby umierają od udanej premiery.",
            ["skill.data.title"] = "INŻYNIERIA DANYCH",
            ["skill.data.what"] = "Wyciąganie więcej z tego samego tekstu. Czyszczenie, deduplikacja, układanie, cała ta nieefektowna robota, która decyduje, ile z korpusu było warte przeczytania.",
            ["skill.data.affects"] = "Efektywną jakość korpusu, jaki masz, więc tani korpus w dobrych rękach bije drogi w złych.",
            ["skill.data.high"] = "Możesz konkurować danymi, na które było cię stać, a nie tymi, na które nie było. Najtańsza przewaga z tej listy.",
            ["skill.data.low"] = "Musisz jakość kupić, a nie zrobić, a licencjonowane archiwa negocjuje się długo i drogo.",
            ["skill.safety.title"] = "BEZPIECZEŃSTWO",
            ["skill.safety.what"] = "Czy zobaczysz problem, zanim zobaczy go regulator. To nie postawa moralna, tylko operacyjna: wiedzieć, co robi twój model, zanim dowie się ktoś inny.",
            ["skill.safety.affects"] = "Dzienną szansę incydentu, czyli największą pojedynczą liczbę w tej grze. Kara to nie słaby kwartał, tylko wtorek, który kończy firmę.",
            ["skill.safety.high"] = "To, co kończy cudze kampanie, w większości ci się nie przydarza. Nigdy nie zobaczysz katastrof, których uniknąłeś, i dlatego łatwo to niedocenić.",
            ["skill.safety.low"] = "Wszystko jest szybsze i tańsze aż do dnia, w którym nie jest. Da się tak grać i to najdroższy sposób na pomyłkę.",

