            ["demo.no_market"] = "JESZCZE NIE MA RYNKU",
            ["demo.nobody_served"] = "Nikt nikogo nie obsługuje.",
            ["finance.books_start"] = "Księgi zaczynają się pierwszego dnia, w którym firma cokolwiek wyda albo zarobi.",
            ["marketing.floor_note"] = "Bycie używanym to już bycie znanym. Firma, którą ludzie mają na usłudze, nie staje się anonimowa, więc ta podłoga rośnie razem z odbiorcami, których trzymasz.",
            ["marketing.nothing_booked"] = "Nic nie wykupione. Słyszeli o tobie tylko ci, którzy już korzystają z usługi.",
            ["research.shares_fleet"] = "Badania dzielą flotę z treningiem, ulepszeniami i programami rodzin. Zwolnij trochę mocy albo dokup wynajmu, a to dokończy się samo.",
            ["site.scene_stale"] = "Pokój istnieje, ale scena nie została przebudowana od czasu podpięcia. Uruchom Scaling Laws, Rebuild scenes.",
            ["site.no_floor_spare"] = "Nie ma tu wolnej podłogi. Sofa, ławka, szafa i schody już się stykają, a cokolwiek jeszcze stałoby na ich środku. Wynajmij piętro, a sklep się otworzy.",
            ["team.both_routes"] = "Obie drogi wracają po dwóch do czterech dni i obie kończą się w skrzynce stawką do uzgodnienia. Różni je to, kto się odezwie.",
            ["labs.nothing_known"] = "Nie wydarzyło im się jeszcze nic, o czym wiedziałby ktokolwiek spoza firmy.",
            ["shelf.scores_today"] = "Ma tyle, ile ma, licząc od dzisiaj. Czekanie nie kosztuje wprost i kosztuje pozycję każdego dnia, bo norma pod spodem cały czas rośnie.",
            ["hiring.three_ways"] = "Trzy sposoby na znalezienie kogoś i żaden nie jest najlepszy. Zlecenie jest tanie i płytkie, urząd jest wolny i darmowy, a wyszukanie specjalisty jest drogie i znajduje dokładnie tego, o kogo poprosiłeś.",
            ["hiring.register_header"] = "WOJEWÓDZKI URZĄD PRACY  //  DEPARTAMENT PRACY I SPRAW SOCJALNYCH\nDZIAŁ IV - POŚREDNICTWO DLA ZAWODÓW TECHNICZNYCH",
            ["hiring.register_notice"] = "UWAGA: Oceny kandydatów są deklarowane samodzielnie na formularzu E-11/b i nie były niezależnie zweryfikowane. Urząd nie ponosi odpowiedzialności wynikającej z pośrednictwa. Czas rozpatrzenia wynosi 2-4 dni robocze.",
            ["hiring.register_footer"] = "Usługa świadczona nieodpłatnie. Obowiązują stawki standardowe. Ostatnia aktualizacja: 14.03.2009.",
            ["menu.create_company"] = "STWÓRZ WŁASNĄ FIRMĘ",
            ["menu.begin_january"] = "ZACZYNAMY, STYCZEŃ 2022",
            ["menu.pick_a_lab"] = "Najpierw wybierz lab.",
            ["menu.needs_a_name"] = "Założyciel potrzebuje imienia. Trafia na stronę firmy.",
            ["menu.company_name"] = "Nazwa firmy",
            ["manage.price_note"] = "Cena rusza reputacją w obie strony i rusza nią logarytmicznie, więc obniżka o połowę jest lubiana mniej więcej tak samo, jak podwojenie jest źle przyjmowane. Dźwignia jest na ekranie biznesowym.",
            ["manage.archive_empty"] = "Archiwum zapełnia się, gdy pierwszy model trafi na rynek. Przebiegów leżących na półce w nim nie ma, bo nigdy nie były w sprzedaży.",
            ["manage.withdraw_note"] = "Wycofanie jest nieodwracalne. Linia przestaje konkurować, a flota, której używała, wraca do wszystkiego innego.",
            ["create.nothing_else"] = "Nic więcej do ustawienia. Ekran wydania będzie czekał, kiedy zechcesz.",
            ["create.subscription_note"] = "Abonament ignoruje stawkę rynkową, co chroni dobrą pozycję i zamyka w złej. Ustaw wysoko, a mniej ludzi się zapisze; ustaw nisko, a obsługujesz tokeny ze stratą w chwili, gdy granica możliwości się przesunie.",
            ["create.precision_note"] = "Węższe liczby przepuszczają ich więcej przez ten sam klaster. Kosztuje to nie gorszy model, tylko mniej przewidywalny.",
            ["create.depth_note"] = "Głębokość jest sekwencyjna, a szerokość równoległa, więc te same parametry ułożone głęboko myślą lepiej i kosztują więcej za token, codziennie, zawsze.",
            ["create.quality_note"] = "Ląduje w obu członach naraz: mniej tokenów, każdy wart więcej. Czy to się opłaca, zależy od tego, czy przebieg miał tokeny do zmarnowania, a na to pas z poprzedniego etapu już odpowiedział.",
            ["create.rent_note"] = "Wynajęta moc jest kontraktowana w petaflopsach, a nie w sztukach, więc rachunek nie rusza się sam, kiedy chmury zmieniają generację. Nigdy się nie starzeje i nalicza się każdego dnia, w którym ją trzymasz, niezależnie od tego, czy cokolwiek robi.",
            ["create.safety_note"] = "Moduły nakładają się na to, co zostało, zamiast się sumować, więc dwa na pół siły to nie jeden na pełnej. Nic tutaj nie osiąga pewności, a ochrona podróżuje z tym modelem, nie z firmą: wybadanie poziomu w przyszłym roku nie utwardza modelu wydanego dzisiaj.",
            ["model.design_run"] = "Zaprojektuj przebieg treningowy od zera. Miesiące i największy rachunek, jaki firma płaci.",
            ["news.strap"] = "Wszystko, co się wydarzyło, i to, co ktoś ci sprzeda o tym, co wydarzy się dalej.",
            ["room.strap"] = "Cztery szafy w piwnicy. Taniej za petaflop niż cokolwiek, co wynajmiesz, i przychodzi z problemami rzeczy fizycznych: miejsce, prąd i ciepło.",
            ["room.already"] = "Już ją masz.",
