            ["relation.friendly.note"] = "Odebraliby telefon i mogliby się zgodzić.",
            ["relation.neutral.note"] = "Konkurencyjnie i profesjonalnie. Nic między wami nie zaszło.",
            ["relation.tense.note"] = "Chłodnieje. Coś już zaszło i zajdzie coś jeszcze.",
            ["relation.hostile.note"] = "Celowo działają przeciwko twoim interesom.",
            ["relation.rivalry.note"] = "Aktywnie szukają sposobu, żeby cię to kosztowało.",
            ["relation.title"] = "JAK CIĘ WIDZĄ",
            ["labtrait.title"] = "JACY SĄ",
            ["labtrait.fearless"] = "Nieustraszony",
            ["labtrait.fearless_note"] = "Wydaje największą rzecz, na jaką go stać, w dniu, w którym go na nią stać. Będzie pierwszy częściej, niż powinien, a gdy się pomyli, pomyli się publicznie.",
            ["labtrait.patient"] = "Cierpliwy",
            ["labtrait.patient_note"] = "Czeka na kolejną generację krzemu i przechodzi ponad wszystkimi. Cichy przez rok, a rok, w którym przestaje być cichy, jest tym, który cię kosztuje.",
            ["labtrait.undercutting"] = "Podcinający",
            ["labtrait.undercutting_note"] = "Wygrywa ceną. Cokolwiek bierzesz, oni wezmą mniej, i nie przeszkadza im nie zarobić na kliencie, na którego liczyłeś.",
            ["labtrait.open"] = "Otwarty",
            ["labtrait.open_note"] = "Oddaje wagi i bierze zasięg zamiast marży. Trudno go przebić ceną i nie da się przebić dystrybucją.",
            ["labtrait.institutional"] = "Korporacyjny",
            ["labtrait.institutional_note"] = "Sprzedaje instytucjom, a nie ludziom. Wolniej się rusza i znacznie trudniej go wyprosić, gdy już gdzieś wejdzie.",
            ["labtrait.deep"] = "Głębokie kieszenie",
            ["labtrait.deep_note"] = "Stoją za nim pieniądze, których nie tłumaczy jego własny przychód. Może przegrywać dłużej niż ty.",
            ["labtrait.expanding"] = "Rozpędzony",
            ["labtrait.expanding_note"] = "Otwiera się wszędzie naraz. Każde otwarte biuro to rynek, na którym oni są, a ciebie nie ma.",
            ["labtrait.wobbling"] = "Chwiejny",
            ["labtrait.wobbling_note"] = "Publicznie w tarapatach. Nadal handluje, już nie nadaje tempa, i warto patrzeć, co zrobi, gdy przestanie mieć czym zapłacić za to, co obiecał.",
            ["labtrait.absorbed"] = "Wchłonięty",
            ["labtrait.absorbed_note"] = "Ludzie i modele poszli gdzieś większego. Nazwa może nadal wisieć na drzwiach.",
            ["labtrait.hostile"] = "Wrogi",
            ["labtrait.hostile_note"] = "Gra przeciwko twoim interesom celowo, a nie przy okazji konkurowania.",
            ["labtrait.veteran"] = "Weteran",
            ["labtrait.veteran_note"] = "Pracowali nad tym, zanim był rynek, dla którego można było nad tym pracować. Wiedzą, gdzie leżą trupy, w tym część własnych.",
            ["labtrait.newcomer"] = "Nowicjusz",
            ["labtrait.newcomer_note"] = "Zaczęli po starcie wyścigu. Wszystko, co mają, zbudowali publicznie i w pośpiechu.",
            ["labtrait.scarred"] = "Poobijany",
            ["labtrait.scarred_note"] = "Przeszli przez coś publicznie i nadal handlują. Cokolwiek to było, przetrwali, a firmy, które przeżyją jedno, zwykle widzą następne z daleka.",
            ["labtrait.leading"] = "Na czele",
            ["labtrait.leading_note"] = "Najlepsza rzecz na rynku jest dziś ich, i na tyle wyraźnie, że nikt się nie spiera. Cokolwiek planujesz, to jest liczba, którą musisz pobić.",
            ["labtrait.quiet"] = "Cichy",
            ["labtrait.quiet_note"] = "Od dawna nic nie wydali. Albo szykuje się coś dużego, albo coś poszło źle w budynku, do którego nikt nie zagląda.",
