            ["effect.days_left"] = "zostało {0} dni",
            ["world.source"] = "SERWIS",
            ["world.chipsact.head"] = "Pięćdziesiąt dwa miliardy na budowę fabryk u siebie",
            ["world.chipsact.body"] = "Publiczne pieniądze, z których w tym roku nie powstanie ani jeden wafel. Wszystko na tej liście do tej pory utrudniało dostęp do krzemu; to pierwsza rzecz w drugą stronę i zajmie jej cztery lata.",
            ["world.researchweights.head"] = "Mocny model trafia do badaczy przez formularz",
            ["world.researchweights.body"] = "Dostęp na wniosek, wagi w komplecie, przy założeniu, że nikt ich nie poda dalej. To założenie wytrzymuje tydzień.",
            ["world.frontierjump.head"] = "Model, dla którego wszyscy się przesiadają",
            ["world.frontierjump.body"] = "Nie tańszy token i nie szerszy lejek. Powód, żeby ludzie, którzy raz spróbowali, uznali to za zabawkę i odeszli, wrócili i spojrzeli jeszcze raz.",
            ["world.pauseletter.head"] = "Tysiące podpisują list z prośbą o półroczną przerwę",
            ["world.pauseletter.body"] = "Nikt nie przerywa. Zmienia się to, że przez sezon każdy kupujący chce wiedzieć, czy rzecz, od której ma zależeć, powstała ostrożnie.",
            ["world.nationalblock.head"] = "Kraj wyłącza asystenta w swoich granicach",
            ["world.nationalblock.body"] = "Regulator, skarga o ochronę danych i usługa, która po prostu przestaje odpowiadać całemu krajowi. Pierwszy raz, kiedy ktokolwiek dowiedział się, że to można zabrać.",
            ["world.devday.head"] = "Druga duża obniżka w tym roku, ze sceny",
            ["world.devday.body"] = "Cokolwiek zostało z marży na tokenie po wiośnie, poszło tutaj. Sprzedaż tokenów jest teraz biznesem wolumenowym, niezależnie od tego, czy ktoś to planował.",
            ["world.boardcrisis.head"] = "Zarząd odwołuje szefa i przyjmuje go z powrotem w pięć dni",
            ["world.boardcrisis.body"] = "W technologii nic się nie zmieniło. Wszyscy, którzy na niej zbudowali, spędzili tydzień na ustalaniu, co zrobią, jeśli firma po prostu przestanie istnieć w piątek.",
            ["world.openagain.head"] = "Mocniejsze otwarte wagi i nikt już się nie dziwi",
            ["world.openagain.body"] = "Trzeci raz w osiemnaście miesięcy. To, co było wydarzeniem, jest teraz harmonogramem wydań, a podłoga pod ceną opada razem z nim.",
            ["world.vetoed.head"] = "Ustawa o bezpieczeństwie przechodzi obie izby i zostaje zawetowana",
            ["world.vetoed.body"] = "Papierologia, którą wszyscy zaczęli już wpisywać w budżety, nie przychodzi. Warto to zauważyć właśnie dlatego, że to jedyny raz w tej dekadzie, gdy reżim poszedł w drugą stronę.",
            ["world.parissummit.head"] = "Trzeci szczyt, a bezpieczeństwa nie ma już w nazwie",
            ["world.parissummit.body"] = "Dwa lata temu sala martwiła się tym, co to potrafi. W tym roku martwi się tym, kto będzie to miał na własność.",
            ["world.projection"] = "Prognoza. Tak gra przewiduje bieg rzeczy, a nie coś, co zostało ogłoszone.",
            ["world.ukraine.head"] = "Wojna zamyka dostawy, o których nikt nie myśli",
            ["world.ukraine.body"] = "Duża część oczyszczonego neonu, na którym stoi światowa litografia układów, pochodziła z jednego kraju i właśnie się skończyła. Neonu nie kupuje nikt; wszyscy kupują to, co z niego powstaje.",
            ["world.shanghai.head"] = "Miasto, które montuje świat, staje na dwa miesiące",
            ["world.shanghai.body"] = "Twardy lockdown w największym regionie produkcji elektroniki na świecie. Zamówienia złożone w tym kwartale przyjdą w następnym, a te już złożone są gdzieś na statku.",
            ["world.openweights.head"] = "Zdolny model wychodzi razem z wagami",
            ["world.openweights.body"] = "Po raz pierwszy każdy może pobrać coś dobrego i uruchomić u siebie. Pod każdym cennikiem w branży leży teraz darmowa alternatywa.",
            ["world.embargo.head"] = "Kontrola eksportu obejmuje najlepsze akceleratory",
            ["world.embargo.body"] = "Najszybszego krzemu nie można już sprzedawać na jego największy rynek. Popyt nie znika, gdy podaż zmienia kierunek; przenosi się gdzie indziej, a to gdzie indziej to kolejka, w której stoisz.",
            ["world.chatlaunch.head"] = "Asystent czatowy wychodzi publicznie i świat to zauważa",
            ["world.chatlaunch.body"] = "W tym tygodniu nic się w technologii nie zmieniło. Zmieniło się to, że ludzie, którzy nigdy nie słyszeli tych słów, chcą tego używać, wszyscy naraz, a rynek, który wyobrażano sobie dekadę, przyszedł w pięć dni.  Lab, który za tym stoi, na tym nie zarabia. I nie musi.",
            ["world.searchrace.head"] = "Dwie największe firmy software'owe wstawiają asystentów do wyszukiwarek",
            ["world.searchrace.body"] = "W odstępie jednego dnia. Cokolwiek zostawało z akceleratorów w zeszłym miesiącu, jest teraz zaklepane na dwa lata.",
            ["world.apicut.head"] = "Ze stawki rynkowej znika rząd wielkości",
            ["world.apicut.body"] = "Jedno ogłoszenie i milion tokenów kosztuje dziesiątą część tego, co kosztował. Każdy, kto sprzedaje tokeny, musi teraz tłumaczyć, dlaczego jego są warte więcej.",
            ["world.weightsleak.head"] = "Wagi z czołówki wyciekają do otwartego internetu",
            ["world.weightsleak.body"] = "Udostępnione badaczom przez formularz, w torrentach w ciągu tygodnia. Podłoga pod ceną tokena przestaje być teoretyczna.",
            ["world.openlicence.head"] = "Otwarte wagi przychodzą z licencją komercyjną",
            ["world.openlicence.body"] = "To samo jeszcze raz, tym razem celowo, i z pozwoleniem na zbudowanie na tym firmy. Najtańszy konkurent na twoim rynku nie kosztuje nic i nigdy nie wystawia faktury.",
            ["world.summit.head"] = "Rządy zgadzają się, że ktoś powinien to sprawdzać",
            ["world.summit.body"] = "Deklaracja, a nie ustawa, podpisana przez wystarczająco wiele krajów. Ewaluacja przestaje być ciekawostką badawczą, a zaczyna być czymś, o co pyta kupujący.",
            ["world.copyright.head"] = "Gazeta pozywa o to, na czym trenowano modele",
            ["world.copyright.body"] = "Każdy korpus w branży jest teraz pytaniem, na które ktoś może musieć odpowiedzieć w sądzie, a kupujący zaczęli pytać, skąd wzięły się dane, zanim spytają, co model potrafi.",
            ["world.aiact.head"] = "Przechodzi pierwszy kompleksowy reżim prawny",
            ["world.aiact.body"] = "Dokumentacja, ewaluacja i papiery przed premierą, a nie po niej. Nic z tego nie robi lepszego modelu, a wszystko zabiera kalendarz, czyli jedyną rzecz, której w tym biznesie nie da się odkupić.",
            ["world.picksandshovels.head"] = "Firma sprzedająca łopaty jest teraz najcenniejsza",
            ["world.picksandshovels.body"] = "Warta więcej niż którakolwiek z firm, które od niej kupują. Warto się nad tym chwilę zatrzymać, jeśli zastanawiałeś się, kto naprawdę na tym wygrywa.",
            ["world.reasoning.head"] = "Modele zaczynają myśleć, zanim odpowiedzą",
            ["world.reasoning.body"] = "Wydawanie mocy w chwili zadania pytania, a nie tylko podczas treningu. Ten sam krzem nagle kupuje więcej, i to pierwsza dobra wiadomość dla strony podażowej od dwóch lat.",
            ["world.nuclear.head"] = "Centrum danych restartuje elektrownię jądrową, żeby się nakarmić",
            ["world.nuclear.body"] = "Sieć energetyczna jest przebudowywana i nie jest przebudowywana pod tych, którzy trzymają cztery szafy w piwnicy. Taryfa dla małych to zauważy.",
            ["world.cheapmodel.head"] = "Model wytrenowany za ułamek ceny dorównuje drogim",
            ["world.cheapmodel.body"] = "Nie lepszy model. Model mniej więcej tak samo dobry, który kosztował mniej więcej nic, co jest gorszą wiadomością dla każdego, kto sprzedaje. Stawka rynkowa idzie za nim w dół i już nie wróci.",
            ["world.stargate.head"] = "Ogłoszono pół biliona dolarów na moc obliczeniową",
            ["world.stargate.body"] = "Ogłoszono, nie zbudowano. Ale każdy, kto dostarcza akceleratory, przeczytał ten sam komunikat i odpowiednio poprawił swój portfel zamówień.",
            ["world.selloff.head"] = "Rynek odkrywa, że wydajność to nie popyt",
            ["world.selloff.body"] = "Jedna piąta wartości najcenniejszej firmy świata w jednej sesji, na teorii, że skoro modele tanieją, to łopaty przestaną się sprzedawać. Teoria jest błędna i minie rok, zanim stanie się to oczywiste.",
            ["world.gpai.head"] = "Zaczynają obowiązywać wymogi dla modeli ogólnego przeznaczenia",
            ["world.gpai.body"] = "Ta część reżimu, która była za dwa lata, jest teraz problemem na ten kwartał i najmocniej uderza w tych, którzy mają najmniej papierów już napisanych.",
            ["world.datawall.head"] = "Publiczny internet kończy się na dobrym tekście",
            ["world.datawall.body"] = "Nie cały tekst. Tekst warty trenowania. Od teraz korpus się wytwarza, a nie znajduje, a wytworzenie go kosztuje moc, która wcześniej szła w model.",
            ["world.liquidcooling.head"] = "Chłodzenie cieczą przestaje być egzotyką",
            ["world.liquidcooling.body"] = "Standardowe części, zwyczajni dostawcy i szafa, która mieści znacznie więcej niż kiedyś. Najtańszy przyrost mocy od lat, i przychodzi do wszystkich naraz.",
            ["world.braindrain.head"] = "Badacze odchodzą do mniejszych pokojów",
            ["world.braindrain.body"] = "Wystarczająco wielu naraz, żeby tempo wyraźnie zwolniło. To, ile jeden z nich jest wart, poszło w górę i nie spadnie, dopóki jest gdzie odejść.",
            ["world.agents.head"] = "Agenci zaczynają wykonywać pracę, a nie ją opisywać",
            ["world.agents.body"] = "Popyt, jakiego ten rynek nie widział: nie ludzie zadający pytania, tylko oprogramowanie chodzące godzinami w czyimś imieniu. Ogromny i absolutnie bezlitosny wobec czasów odpowiedzi.",
            ["effect.pulling"] = "Ciągnie popyt o {0} w tej chwili.",
            ["effect.about"] = "~{0}",
            ["effect.roughly_left"] = "Zostało jakieś {0}, na tyle, na ile ktokolwiek tu wie.",
            ["effect.open_ended"] = "Bezterminowa. Trwa, dopóki jej nie zerwiesz, i płacisz za każdy dzień.",
            ["effect.booked_left"] = "Zarezerwowana jeszcze na {0}.",
