            ["smear.briefing.name"] = "PODRZUCONY TEMAT",
            ["smear.briefing.note"] = "Dziennikarz dostaje historię i kierunek. Większy zasięg, ale ktoś już zna twoje nazwisko.",
            ["smear.report.name"] = "RAPORT",
            ["smear.report.note"] = "Zamówione badanie z wnioskiem ustalonym przed pracą. Trudno je zignorować, a zlecona praca zostawia papiery.",
            ["smear.campaign.name"] = "KAMPANIA",
            ["smear.campaign.note"] = "Wykupione zasięgi wszędzie naraz, przez dwa tygodnie. Najgłośniejsze, co możesz zrobić, i niemal rzut monetą o wpadkę.",
