            ["scandal.stagnation"] = "Od bardzo dawna nic nowego nie wyszło z {0} i ktoś napisał to wprost.",
            ["scandal.corners"] = "{0} sprzedają model z wyraźnie pominiętą pracą nad bezpieczeństwem.",
            ["office.soon"] = "WKRÓTCE",
            ["office.soon.note"] = "Jeszcze nie zbudowane. Jest tu po to, żebyś widział, dokąd prowadzi drabina.",
            ["office.soon.tower.name"] = "WŁASNA WIEŻA",
            ["office.soon.tower.note"] = "Budynek z twoją nazwą na szczycie i kosztami utrzymania małego miasta.",
            ["office.soon.campus.name"] = "KAMPUS BADAWCZY",
            ["office.soon.campus.note"] = "Kilka lokalizacji, jedna lista płac i pułap zatrudnienia, którego nic innego nie dosięga.",
            ["intel.benefits.show"] = "ZOBACZ KORZYŚCI",
            ["intel.benefits.hide"] = "UKRYJ KORZYŚCI",
            ["intel.benefits.press"] = "Żadnego wydarzenia już nie przeoczysz. Premiery sprzętu, ruchy regulatorów i wydania konkurencji docierają do ciebie, kiedy jeszcze da się coś z tym zrobić, a nie w tym samym tygodniu co do wszystkich. Tanio, szeroko i wystarczająco często błędnie, żebyś musiał myśleć przy czytaniu.",
            ["intel.benefits.known"] = "Co dzieje się wewnątrz innych labów, a nie co ogłosiły. Kto zatrudnia, kto po cichu zostaje w tyle, która firma jest o jeden zły kwartał od przejęcia. Tablica mówi, gdzie rywal stoi dzisiaj; to mówi, dokąd zmierza.",
            ["intel.benefits.trend"] = "Premiery słabych generacji złamały nie jedną firmę, która zdążyła się już na nie zdecydować. Ekspercka grupa badawcza czyta plany krzemu miesiące naprzód, więc możesz poczekać na część, którą warto kupić, zamiast kupić tę, która akurat wyszła.",
            ["phone.menu.title"] = "TELEFON",
            ["phone.menu.call"] = "Zadzwoń do {0}",
            ["phone.menu.close"] = "Odłóż telefon",
            ["phone.menu.back"] = "Wróć",
            ["phone.menu.resume"] = "{0}, w trakcie",
            ["phone.menu.resume.note"] = "Kliknij, żeby ruszyć dalej od miejsca, w którym stanęliście",
            ["phone.ask.business"] = "Jak idzie biznes?",
            ["phone.emil.resume"] = "Dobra, lecimy dalej.",
            ["phone.emil.good"] = "Szczerze? Lepiej, niż powinno. Kwartał na plusie, jestem {0} na tablicy, co moja księgowa uparcie nazywa nie-osobowością. A u ciebie?",
            ["phone.emil.steady"] = "Po staremu. {0} miejsce, faktury wychodzą, nikt o nas nie pisze. Nie porywa, ale płaci za biuro. A ty?",
            ["phone.emil.bad"] = "Nie pytaj. Kwartał na minusie, jestem {0}, czyli niżej, niż chcę powiedzieć na głos. Odbije. Zwykle odbija.",
            ["room.needs_hardware"] = "Serwerownia mieści karty, które masz na własność, a jeszcze nie możesz mieć żadnej. {0}",
            ["shell.screen_failed"] = "TEN EKRAN SIĘ NIE ZBUDOWAŁ",
            ["shell.screen_failed.where"] = "Coś poszło nie tak przy rysowaniu {0}. Reszta gry działa: użyj paska, żeby przejść gdzie indziej.",
            ["shell.screen_failed.note"] = "Jeśli możesz, wyślij tę linijkę razem ze zgłoszeniem. Mówi dokładnie, gdzie szukać.",
            ["mg.versions"] = "WERSJE",
            ["mg.versions.strap"] = "Na której wersji naprawdę siedzą twoi użytkownicy. Rynek czyta średnią z nich, a nie najlepszą rzecz, jaką kiedykolwiek wydałeś.",
            ["mg.desk.strap"] = "Co mówią liczby. Utrzymani użytkownicy, co o tobie myślą i ile kosztuje ich zatrzymanie.",
            ["mg.archive.strap"] = "Każdy model, jaki firma wystawiła na sprzedaż, od najnowszego. Ile każdy dostał punktów, ile zarobił i czy ktokolwiek jeszcze go używa.",
            ["mg.on_the_shelf"] = "{0} czeka na półce. Strona potrzebuje czegoś, co można na niej pokazać.",
            ["mg.nothing_released"] = "Żaden model nie został wydany. Wytrenuj jeden, wydaj go, a to stanie się stroną, na którą trafiają ludzie.",
            ["mg.flagship_line"] = "model {0}  ·  linia {1}  ·  wydany {2} temu",
            ["mg.people_use_it"] = "{0} osób z tego korzysta",
