            ["mg.everyone_pays"] = "Każdy, kto chce spróbować, najpierw płaci.",
            ["mg.cheapest_hardest"] = "Najtańszy w obsłudze, najtrudniejszy do odkrycia.",
            ["mg.k_tokens_a_day"] = "{0} tys. tokenów dziennie",
