            ["walk.room.open"] = "No dobra, piwnica. Wszystko czego potrzebujesz jest na tym pasku z boku. Nic tu nie kosztuje, dopóki czegoś nie kupisz, więc najpierw się rozejrzyj.",
            ["walk.room.shop"] = "To są szafy. Ta tania to otwarta rama: teraz w porządku, a ugotuje się w chwili, gdy karty się zagrzeją. Droższe zniosą więcej ciepła, zanim zaczną się dławić.",
            ["walk.room.buy"] = "Wybierz jedną i ją kup. Trafi do magazynu, nie na podłogę, więc wciąż możesz zmienić zdanie, gdzie ma stanąć.",
            ["walk.room.carry"] = "Teraz ją niesiesz. Pola, które ją przyjmą, są podświetlone.",
            ["walk.room.stand"] = "Postaw ją gdziekolwiek. Później przesuniesz ją za darmo, więc się nie zastanawiaj.",
            ["walk.room.open_rack"] = "Teraz kliknij samą szafę. To ją otworzy, żebyś zobaczył, co jest w środku.",
            ["walk.room.fit"] = "Każdy slot przyjmuje kartę albo wentylator. Karty dają moc, wentylatory nie pozwalają jej się dławić. Włóż coś.",
            ["walk.room.done"] = "I to tyle. To teraz twoja własna maszyna, więc za tę część już nigdy nie płacisz wynajmu. Pilnuj temperatury i wróć, gdy karty zaczną się starzeć.",
            ["guide.step.compute_cap"] = "Słuchaj, póki co trzymaj się kwoty przy wynajmie serwerów do 80 tysięcy. Serio, zapisz sobie. A gdy skończymy zaraz cię wprowadzać w biznes, mam dla ciebie prezent, który uwolni cię od wynajmów.",
            ["walk.chip.kicker"] = "PORADNIK",
            ["walk.chip.call"] = "zadzwoń do Emila",
            ["phone.menu.messenger"] = "Messager dIn",
            ["phone.day"] = "Dzień {0}",
            ["phone.thread.empty"] = "Jeszcze nic tu nie ma. Napisz do niego.",
            ["phone.compose.write"] = "Napisz / Zadzwoń",
            ["phone.compose.guides"] = "MOŻE CIĘ PRZEPROWADZIĆ PRZEZ",
            ["phone.ask.guide"] = "Przeprowadzisz mnie przez to? {0}",
            ["phone.guide.now"] = "Mogę ci pokazać teraz, jeśli masz chwilę. Powiedz słowo i przejdziemy przez to razem, krok po kroku.",
            ["phone.guide.yes"] = "Tak, pokaż mi teraz",
            ["phone.guide.later"] = "Nie teraz",
            ["phone.guide.no"] = "Nie teraz, odezwę się.",
            ["creator.click_map"] = "Kliknij gdziekolwiek na mapie, by wybrać region, albo kliknij jedno z szesnastu państw, by załatwić to od razu.",
            ["creator.pick_country_hint"] = "Wybierz państwo z mapy albo z tej listy.",
            ["research.era.5"] = "ERA 5   SPRAWY PAŃSTWOWE   OD 2029",
            ["sector.bureaucracy"] = "Biurokracja",
            ["sector.bureaucracy.blurb"] = "Pozwolenia, świadczenia, deklaracje podatkowe, księgi wieczyste. Nikt tego nie kocha i nikt nie zauważa, gdy działa, więc to jedyny sektor, w którym błąd da się przeżyć.",
            ["sector.education"] = "Edukacja",
            ["sector.education.blurb"] = "Program nauczania, ocenianie, przydział nauczycieli. Efekty widać powoli, a szkody jeszcze wolniej — i to działa w obie strony.",
            ["sector.health"] = "Zdrowie",
            ["sector.health.blurb"] = "Triaż, grafiki, epidemiologia, zamówienia szpitali na przyszły miesiąc. Pierwszy sektor, w którym pomyłkę liczy się w ludziach.",
            ["sector.logistics"] = "Logistyka",
            ["sector.logistics.blurb"] = "Transport, porty, harmonogram sieci energetycznej. Największe ciągłe obciążenie, jakie ma państwo, i psuje się publicznie w ciągu kilku godzin.",
            ["sector.economy"] = "Gospodarka",
            ["sector.economy.blurb"] = "Modelowanie fiskalne i prognoza banku centralnego. Twoje modele zaczynają decydować, ile pieniądz będzie wart w przyszłym kwartale.",
            ["sector.security"] = "Bezpieczeństwo narodowe",
            ["sector.security.blurb"] = "Policja, wyłudzenia, granice. Ogromne pieniądze i pierwszy sektor, w którym awaria staje się aferą o firmie, a nie o państwie.",
            ["sector.diplomacy"] = "Dyplomacja",
            ["sector.diplomacy.blurb"] = "Redagowanie traktatów, modelowanie negocjacji, co powiedzieć i kiedy. Dyskretne, świetnie płatne i niemożliwe do wytłumaczenia po fakcie.",
            ["sector.defence"] = "Obrona",
            ["sector.defence.blurb"] = "Doktryna, zakupy, ocena zagrożeń. Najwyższa stawka w grze i jedyny sektor, którego awaria potrafiła zakończyć firmę, która się go podjęła.",
            ["state.already_signed"] = "Już podpisane.",
            ["state.not_signed"] = "Jeszcze bez kontraktu.",
            ["state.needs_liaison"] = "Najpierw potrzebne {0}. Nikt nie podpisuje kontraktu państwowego z firmą, której nie audytował.",
            ["state.needs_record"] = "Twoja pięcioletnia ocena bezpieczeństwa to {0}. Oczekują {1}, a jedyną drogą jest czekanie.",
            ["state.sector_running"] = "Już działa.",
            ["state.sector_not_running"] = "Ten sektor nie działa.",
            ["state.needs_sector"] = "Najpierw musi działać {0}.",
