            ["state.needs_cash"] = "Wdrożenie kosztuje {0}.",
            ["state.sector_holds_up"] = "Na nim opiera się {0}. Najpierw oddaj tamten.",
            ["state.signed.story"] = "Rząd państwa {0} podpisał program narodowy. Modele firmy będą działać wewnątrz systemów państwowych.",
            ["state.sector.story"] = "{0} działa teraz na modelach firmy, za {1} dziennie.",
            ["state.handed_back.story"] = "Firma oddała {0} z powrotem państwu.",
            ["state.failure.story"] = "{0} zawiodła w skali kraju. Firmę obciążono kwotą {1}.",
            ["state.title"] = "PROGRAM PAŃSTWOWY",
            ["state.strap"] = "Prowadzenie części państwa na własnych modelach. Największe pieniądze w grze i jedyne błędy liczone w miliardach.",
            ["state.record"] = "PIĘCIOLETNIA OCENA BEZPIECZEŃSTWA",
            ["state.record.note"] = "To, co widzi rząd, gdy cię sprawdza. Tego akurat nie da się kupić.",
            ["state.sign"] = "PODPISZ PROGRAM",
            ["state.signed_with"] = "Podpisano z {0}, dzień {1}",
            ["state.delivery"] = "REALIZACJA",
            ["state.delivery.note"] = "Ile z tego, co obiecałeś, flota faktycznie pokrywa. Państwo płaci taki właśnie ułamek stawki, a wszystko poniżej pełna zwiększa ryzyko awarii.",
            ["state.risk"] = "DZISIEJSZE RYZYKO AWARII",
            ["state.held"] = "ZAREZERWOWANE DLA PAŃSTWA",
            ["state.held.note"] = "Moc, której nie mają już płacący klienci. Schodzi z góry, przed treningiem i przed klientami.",
            ["state.fee"] = "STAWKA",
