            ["state.failure_cost"] = "GDY ZAWIEDZIE",
            ["state.on_notice"] = "POD NADZOREM. Twoja ocena spadła poniżej tej, na którą podpisali, i dopóki tam jest, ryzyko jest podwojone.",
            ["state.failures_so_far"] = "{0} awarii, wypłacono {1}",
