            ["biz.company_marketing"] = "MARKETING FIRMY",
            ["biz.company_marketing.blurb"] = "Reputacja, powoli, i przetrwa to, że model się zestarzeje.",
            ["biz.model_marketing"] = "MARKETING MODELU",
