            ["bank.run_rate"] = "Roczne tempo przychodów",
            ["bank.founder_stake"] = "Wartość udziału założyciela",
            ["plate.off_duty"] = "{0}, przychodzi {1}:00",
            ["research.operations"] = "OPERACJE",
            ["node.racktelemetry"] = "Telemetria szaf",
            ["node.racktelemetry.desc"] = "Sondy na wlocie i wylocie każdej szafy, z logowaniem, żeby serwerownia przestała być czymś, o czym dowiadujesz się dopiero wtedy, gdy spada przepustowość. To, co zrobi z szafą jeszcze jedna karta, ktoś już policzył; tu chodzi o pokazanie tego na panelu przed jej włożeniem, a nie po.",
            ["node.airflow"] = "Modelowanie przepływu powietrza",
            ["node.airflow.desc"] = "Symulacja całego pomieszczenia, a nie pojedynczej szafy: dokąd naprawdę idzie zimny korytarz, które nawiewy walczą ze sobą i ile wywiewu to zawrócone ciepłe powietrze, które nigdy stąd nie wyszło. Każda szafa na podłodze oddaje przez to trochę więcej ciepła.",
            ["node.liquidloops"] = "Obiegi cieczy",
            ["node.liquidloops.desc"] = "Instalacja, pompy i obieg odprowadzania ciepła dla wanien immersyjnych. Powietrze kończy się dużo wcześniej niż krzem, a porządnie obsłużona wanna przestaje się przejmować tym, jak gorący jest tegoroczny akcelerator.",
            ["node.substation"] = "Własna stacja transformatorowa",
            ["node.substation.desc"] = "Serwerownia schodzi z licznika domowego. Transformator, opomiarowane przyłącze przemysłowe i papierologia, która idzie za pobieraniem takiej mocy przy ulicy z domami jednorodzinnymi.",
            ["node.agi"] = "Inteligencja ogólna",
            ["node.agi.desc"] = "Nie lepszy model. Model, któremu nie trzeba mówić, na jaki rodzaj problemu patrzy. Wszystko po tym dotyczy już tego, na co go skierujesz.",
            ["node.assimilation"] = "Asymilacja w czasie rzeczywistym",
            ["node.assimilation.desc"] = "Czytanie państwa na bieżąco: każda transakcja, każda dostawa, każde zgłoszenie jako jedno ciągłe wejście, a nie raport, który przychodzi w piątek.",
            ["node.liaison"] = "Łącznik rządowy",
            ["node.liaison.desc"] = "Poświadczenia bezpieczeństwa, stałe biuro i ktoś, czyja cała praca to numer telefonu do rządu. Nikt nie podpisuje kontraktu państwowego z firmą, której nie audytował od lat.",
            ["node.oversight"] = "Ciągły nadzór",
            ["node.oversight.desc"] = "Drugi model, którego jedynym zadaniem jest pilnowanie pierwszego, w sektorach, które mają znaczenie, i który nigdy nie jest tym, który podejmuje decyzję.",
            ["node.redundant"] = "Redundantne wnioskowanie",
            ["node.redundant.desc"] = "Obciążenie państwa idzie dwiema niezależnymi ścieżkami, więc niedobór mocy degraduje usługę zamiast ją zatrzymywać. Kosztuje moc, gdy jest, i ratuje firmę, gdy mocy zabraknie.",
            ["rack.next_card"] = "JESZCZE JEDNA KARTA",
            ["rack.next_reading"] = "{0}, {1} pełnej prędkości",
            ["rack.next_full"] = "Brak wolnego slotu",
            ["create.corpus_market"] = "DOSTĘPNE NA RYNKU",
            ["create.corpus_offer"] = "{0} tokenów, jakość {1}",
            ["create.panel.what_for"] = "DO CZEGO TO JEST",
            ["create.panel.free_tier"] = "DARMOWY PLAN",
            ["create.panel.subscription"] = "ABONAMENT",
            ["create.panel.readout"] = "ODCZYT SKALOWANIA",
            ["create.panel.notes"] = "UWAGI",
            ["create.panel.precision"] = "PRECYZJA",
            ["create.panel.arrangement"] = "UKŁAD",
            ["create.panel.dedup"] = "DEDUPLIKACJA",
            ["create.panel.compute"] = "MOC",
            ["create.panel.projection"] = "PROGNOZA",
            ["create.back"] = "WSTECZ",
            ["create.corpus_toggle"] = "{0}  ({1} tokenów, jakość {2})",
            ["width.fp64"] = "FP64",
            ["width.fp64.pitch"] = "Podwójna szerokość. Nikt już tak nie trenuje i właśnie dlatego to jest to, co ci zostaje, zanim cokolwiek zbadasz. Wolne, i nigdy nie okłamuje cię co do tego, gdzie wyląduje trening.",
            ["width.fp32"] = "FP32",
            ["width.fp32.pitch"] = "Pełna szerokość. O jedną trzecią więcej przez ten sam krzem niż podwójna, i nadal żadnych dramatów na krzywej straty.",
            ["width.bf16"] = "BF16",
            ["width.bf16.pitch"] = "To, w czym trenują wszyscy. Prawie dwukrotna przepustowość pełnej szerokości, bez ryzyka, które niesie osiem bitów.",
            ["width.fp8"] = "FP8",
            ["width.fp8.pitch"] = "Osiem bitów. Prawie dwa razy więcej mocy z tego samego klastra i trening, który potrafi rozsypać się na ostatniej prostej, bez niczego w zamian za wydane pieniądze.",
            ["width.fp8.warning"] = "Wymaga krzemu z 2023 roku. Rozrzut gotowego modelu jest ponad dwa razy większy niż przy BF16, więc to zakład, a nie oszczędność.",
            ["shape.deep"] = "Głęboki",
            ["shape.deep.pitch"] = "Dużo cienkich warstw. Rozumuje w większej liczbie kroków, a każdy krok czeka na poprzedni.",
            ["shape.deep.note"] = "Lepszy na parametr, droższy na token, a opóźnienie widać pod obciążeniem.",
            ["shape.balanced"] = "Zrównoważony",
            ["shape.balanced.pitch"] = "Proporcje, względem których mierzy się wszystko inne w tej grze.",
            ["shape.balanced.note"] = "Dokładnie neutralny. Nic innego w treningu się nie zmienia.",
            ["shape.wide"] = "Szeroki",
            ["shape.wide.pitch"] = "Mało grubych warstw. Mniej głębokości do przemyślenia, a całość dobrze się zrównolegla.",
            ["shape.wide.note"] = "Tańszy w obsłudze niż cokolwiek innego przy tym samym rozmiarze, co się opłaca, gdy odbiorcy są liczni i wrażliwi na cenę.",
            ["dedup.raw"] = "Surowy",
            ["dedup.raw.pitch"] = "Wszystko, co znalazł crawler, razem z powtórzeniami.",
            ["dedup.raw.note"] = "Najwięcej tokenów za te pieniądze, a model część z nich wydaje na naukę tej samej strony dziewięć razy.",
            ["dedup.standard"] = "Standardowy",
            ["dedup.standard.pitch"] = "Dokładne duplikaty usunięte. To, co kompetentny zespół robi bez proszenia.",
            ["dedup.standard.note"] = "Neutralny. To jest punkt odniesienia, który zakładają liczby jakości korpusu.",
            ["dedup.aggressive"] = "Agresywny",
            ["dedup.aggressive.pitch"] = "Także zbliżone duplikaty i szablonowe wypełniacze. Kosztuje jedną piątą korpusu.",
            ["dedup.aggressive.note"] = "Opłaca się, gdy korpus jest większy niż potrzeba treningowi, a marnuje jego jedną piątą, gdy nie jest.",
            ["plan.no_corpus"] = "nie wybrano żadnego użytecznego korpusu",
            ["plan.needs_memory"] = "potrzebuje {0} GB pamięci akceleratorów, flota daje {1} GB",
            ["plan.no_compute"] = "flota nie ma użytecznej mocy",
            ["hosting.growth"] = "Klaster wzrostu",
            ["hosting.growth.pitch"] = "Zarezerwowana moc dla mniej więcej miliona zwykłych kont. Trzyma swoją szybkość wtedy, gdy wspólna pula zaczyna się kolejkować.",
            ["hosting.edge"] = "Warstwa brzegowa",
            ["hosting.edge.pitch"] = "Połowa mocy za te same pieniądze i prawie w ogóle nie zwalnia. Dla produktów sprzedawanych szybkością, a nie rozmiarem.",
            ["hosting.bulk"] = "Przydział hurtowy",
            ["hosting.bulk.pitch"] = "Trzy razy więcej mocy za dwa razy większe pieniądze, na współdzielonym sprzęcie. Kolejkuje się pod obciążeniem jak wszystko inne w puli, a przy tej skali na pewno będzie.",
            ["channel.social"] = "Social media",
            ["channel.social.pitch"] = "Tanie, natychmiastowe i równie szybko o tobie zapomina. Potrafi zajść dalej niż cokolwiek innego tutaj albo nigdzie, i jest jedynym kanałem, który może cię kosztować reputację.",
            ["channel.press"] = "Prasa",
            ["channel.press.pitch"] = "Ledwie rusza liczby i jest jedyną rzeczą, która niezawodnie buduje reputację. Czytają ją klienci korporacyjni, nikt inny.",
            ["channel.radio"] = "Radio",
            ["channel.radio.pitch"] = "Regionalne, stabilne i niemodne. Tanie jak na zasięg i działa jeszcze długo po tym, jak skończą się pieniądze.",
            ["channel.tv"] = "Telewizja",
            ["channel.tv.pitch"] = "Najszerszy zasięg, jaki istnieje, i najwolniej się rozkręca. Na tyle drogi, że krótka kampania to pieniądze wydane, zanim ktokolwiek zdążył zauważyć.",
            ["channel.billboards"] = "Billboardy",
            ["channel.billboards.pitch"] = "Fizyczne, lokalne i nie da się ich pominąć. Wolne, a to, co kupują, zostaje jeszcze przez chwilę po zdjęciu plakatów.",
            ["channel.creators"] = "Twórcy",
            ["channel.creators.pitch"] = "Ktoś z publicznością mówi o tobie. Ostry skok, krótka pamięć i realna szansa, że niewłaściwa osoba powie niewłaściwą rzecz.",
            ["region.america"] = "Ameryka",
            ["region.america.note"] = "Tam, gdzie akceleratory trafiają najpierw, i gdzie wszyscy inni już są.",
            ["region.europe"] = "Europa",
            ["region.europe.note"] = "Taniej się prowadzi, wolniej dostarcza, a regulator przeczyta to, co opublikujesz.",
            ["region.asia"] = "Azja",
            ["region.asia.note"] = "Najbliżej fabryk. Krzem jest tu tani, a uwaga nie.",
            ["country.us"] = "Stany Zjednoczone",
            ["country.us.note"] = "Pierwsi w kolejce po każdą premierę, i tak samo wszyscy inni.",
            ["country.canada"] = "Kanada",
            ["country.canada.note"] = "Badania są tutaj. Kapitał jest jedną granicę dalej.",
            ["country.brazil"] = "Brazylia",
            ["country.brazil.note"] = "O tych użytkowników prawie nikt jeszcze nie walczy.",
            ["country.mexico"] = "Meksyk",
            ["country.mexico.note"] = "Tanio o ludzi, wystarczająco blisko, żeby dowozić.",
            ["country.uk"] = "Wielka Brytania",
            ["country.uk.note"] = "Głęboka ława badawcza, cienki rynek krajowy.",
            ["country.germany"] = "Niemcy",
            ["country.germany.note"] = "Klienci przemysłowi, którzy płacą na czas i czytają umowę.",
            ["country.france"] = "Francja",
            ["country.france.note"] = "Państwowe pieniądze są dostępne, jeśli państwo cię lubi.",
            ["country.poland"] = "Polska",
            ["country.poland.note"] = "Niski podatek, niskie płace, sprzęt przyjeżdża późno.",
            ["country.ireland"] = "Irlandia",
            ["country.ireland.note"] = "Stawka podatku to cała oferta.",
            ["country.switzerland"] = "Szwajcaria",
            ["country.switzerland.note"] = "Drodzy ludzie, tanie podatki, spokojni sąsiedzi.",
            ["country.japan"] = "Japonia",
            ["country.japan.note"] = "Cierpliwi klienci, bezlitosny podatek.",
            ["country.southkorea"] = "Korea Południowa",
            ["country.southkorea.note"] = "Pamięć powstaje tutaj, więc pamięć jest tu tania.",
